context/verif/tb_des_enc.sv:
module tb;

parameter NBW_DATA = 'd64;
parameter NBW_KEY  = 'd64;

logic                clk;
logic                rst_async_n;
logic                i_valid;
logic [1:NBW_DATA] i_data;
logic [1:NBW_KEY ] i_key;
logic                o_valid;
logic [1:NBW_DATA] o_data;

des_enc #(
    .NBW_DATA(NBW_DATA),
    .NBW_KEY (NBW_KEY )
) uu_des_enc (
    .clk        (clk        ),
    .rst_async_n(rst_async_n),
    .i_valid    (i_valid    ),
    .i_data     (i_data     ),
    .i_key      (i_key      ),
    .o_valid    (o_valid    ),
    .o_data     (o_data     )
);

initial begin
    $dumpfile("test.vcd");
    $dumpvars(0,tb);
end

always #5 clk = ~clk;

task Single_test(logic [1:NBW_KEY] key, logic [1:NBW_DATA] data, logic [1:NBW_DATA] expected);
    i_key   = key;
    i_data  = data;
    i_valid = 1;

    @(negedge clk);
    i_valid = 0;

    @(posedge o_valid);
    @(negedge clk);
    if(o_data != expected) begin
        $display("FAIL!");
        $display("Expected %h, got %h", expected, o_data);
    end else begin
        $display("PASS!");
    end
endtask

task Burst_test();
    i_key   = 64'hB1FECAFEBEBAB1FE;
    i_data  = 64'h4321432143214321;
    i_valid = 1;

    @(negedge clk);
    i_data  = 64'h123456789ABCDEF0;

    @(negedge clk);
    i_data  = 64'h1234123412341234;
    i_key   = 64'hABCDABCDABCDABCD;

    @(negedge clk);
    i_valid = 0;

    @(posedge o_valid);
    @(negedge clk);
    if(o_data != 64'h6B85F162427F0DC8) begin
        $display("FAIL!");
        $display("Expected %h, got %h", 64'h6B85F162427F0DC8, o_data);
    end else begin
        $display("PASS!");
    end

    @(negedge clk);
    if(o_valid != 1) begin
        $display("FAIL! o_valid should be asserted here.");
    end
    if(o_data != 64'hB02273A3AD757BDA) begin
        $display("FAIL!");
        $display("Expected %h, got %h", 64'hB02273A3AD757BDA, o_data);
    end else begin
        $display("PASS!");
    end

    @(negedge clk);
    if(o_valid != 1) begin
        $display("FAIL! o_valid should be asserted here.");
    end
    if(o_data != 64'h87C952860A802C4B) begin
        $display("FAIL!");
        $display("Expected %h, got %h", 64'h87C952860A802C4B, o_data);
    end else begin
        $display("PASS!");
    end
    
endtask

initial begin
    clk = 0;
    i_valid = 0;
    rst_async_n = 1;
    #1;
    rst_async_n = 0;
    #2;
    rst_async_n = 1;
    @(negedge clk);

    $display("\nSingle Tests");
    Single_test(64'h0123456789ABCDEF, 64'h0123456789ABCDEF, 64'h56CC09E7CFDC4CEF);
    Single_test(64'h0123456789ABCDEF, 64'hFEDCBA9876543210, 64'h12C626AF058B433B);
    Single_test(64'hBEBACAFE12345678, 64'hFEDCBA9876543210, 64'h00D97727C293BFAC);
    Single_test(64'hBEBACAFE12345678, 64'hB1FECAFEBEBAB1FE, 64'h31F3FE80E9457BED);

    $display("\nBurst Test");
    Burst_test();

    @(negedge clk);
    @(negedge clk);

    $finish();
end

endmodule

context/rtl/des_enc.sv:
module des_enc #(
    parameter NBW_DATA = 'd64,
    parameter NBW_KEY  = 'd64
) (
    input  logic              clk,
    input  logic              rst_async_n,
    input  logic              i_valid,
    input  logic [1:NBW_DATA] i_data,
    input  logic [1:NBW_KEY]  i_key,
    output logic              o_valid,
    output logic [1:NBW_DATA] o_data
);

localparam ROUNDS = 'd16;
localparam EXPANDED_BLOCK = 'd48;
localparam USED_KEY = 'd56;

logic [1:NBW_DATA]     IP;
logic [1:(NBW_DATA/2)] L0;
logic [1:(NBW_DATA/2)] R0;
logic [1:(NBW_DATA/2)] L_ff [1:ROUNDS];
logic [1:(NBW_DATA/2)] R_ff [1:ROUNDS];
logic [1:(USED_KEY/2)] C0;
logic [1:(USED_KEY/2)] D0;
logic [1:(USED_KEY/2)] C_ff [1:ROUNDS];
logic [1:(USED_KEY/2)] D_ff [1:ROUNDS];
logic [1:NBW_DATA]     last_perm;
logic [ROUNDS-1:0]     valid_ff;

always_ff @ (posedge clk or negedge rst_async_n) begin
    if(!rst_async_n) begin
        valid_ff <= 0;
    end else begin
        valid_ff <= {valid_ff[ROUNDS-2:0], i_valid};
    end
end

assign o_valid = valid_ff[ROUNDS-1];

assign IP = {i_data[58], i_data[50], i_data[42], i_data[34], i_data[26], i_data[18], i_data[10], i_data[2],
             i_data[60], i_data[52], i_data[44], i_data[36], i_data[28], i_data[20], i_data[12], i_data[4],
             i_data[62], i_data[54], i_data[46], i_data[38], i_data[30], i_data[22], i_data[14], i_data[6],
             i_data[64], i_data[56], i_data[48], i_data[40], i_data[32], i_data[24], i_data[16], i_data[8],
             i_data[57], i_data[49], i_data[41], i_data[33], i_data[25], i_data[17], i_data[ 9], i_data[1],
             i_data[59], i_data[51], i_data[43], i_data[35], i_data[27], i_data[19], i_data[11], i_data[3],
             i_data[61], i_data[53], i_data[45], i_data[37], i_data[29], i_data[21], i_data[13], i_data[5],
             i_data[63], i_data[55], i_data[47], i_data[39], i_data[31], i_data[23], i_data[15], i_data[7]};

assign L0 = IP[1:NBW_DATA/2];
assign R0 = IP[(NBW_DATA/2)+1:NBW_DATA];

assign C0 = {i_key[57], i_key[49], i_key[41], i_key[33], i_key[25], i_key[17], i_key[ 9],
             i_key[ 1], i_key[58], i_key[50], i_key[42], i_key[34], i_key[26], i_key[18],
             i_key[10], i_key[ 2], i_key[59], i_key[51], i_key[43], i_key[35], i_key[27],
             i_key[19], i_key[11], i_key[ 3], i_key[60], i_key[52], i_key[44], i_key[36]};

assign D0 = {i_key[63], i_key[55], i_key[47], i_key[39], i_key[31], i_key[23], i_key[15],
             i_key[ 7], i_key[62], i_key[54], i_key[46], i_key[38], i_key[30], i_key[22],
             i_key[14], i_key[ 6], i_key[61], i_key[53], i_key[45], i_key[37], i_key[29],
             i_key[21], i_key[13], i_key[ 5], i_key[28], i_key[20], i_key[12], i_key[ 4]};

generate
    for (genvar i = 1; i <= ROUNDS; i++) begin : rounds
        logic [1:EXPANDED_BLOCK] round_key;
        logic [1:(USED_KEY/2)]    C_nx;
        logic [1:(USED_KEY/2)]    D_nx;
        logic [1:USED_KEY]        perm_ch;
        logic [1:(NBW_DATA/2)] R_nx;
        logic [1:EXPANDED_BLOCK] R_expanded;
        logic [1:6] Primitive_input  [1:8];
        logic [1:4] Primitive_output [1:8];
        logic [1:(NBW_DATA/2)] perm_in;

        assign perm_ch = {C_nx, D_nx};
        assign round_key = {perm_ch[14], perm_ch[17], perm_ch[11], perm_ch[24], perm_ch[ 1], perm_ch[ 5],
                            perm_ch[ 3], perm_ch[28], perm_ch[15], perm_ch[ 6], perm_ch[21], perm_ch[10],
                            perm_ch[23], perm_ch[19], perm_ch[12], perm_ch[ 4], perm_ch[26], perm_ch[ 8],
                            perm_ch[16], perm_ch[ 7], perm_ch[27], perm_ch[20], perm_ch[13], perm_ch[ 2],
                            perm_ch[41], perm_ch[52], perm_ch[31], perm_ch[37], perm_ch[47], perm_ch[55],
                            perm_ch[30], perm_ch[40], perm_ch[51], perm_ch[45], perm_ch[33], perm_ch[48],
                            perm_ch[44], perm_ch[49], perm_ch[39], perm_ch[56], perm_ch[34], perm_ch[53],
                            perm_ch[46], perm_ch[42], perm_ch[50], perm_ch[36], perm_ch[29], perm_ch[32]};

        if(i == 1 || i == 2 || i == 9 || i == 16) begin
            if(i == 1) begin
                assign C_nx = {C0[2:(USED_KEY/2)], C0[1]};
                assign D_nx = {D0[2:(USED_KEY/2)], D0[1]};
            end else begin
                assign C_nx = {C_ff[i-1][2:(USED_KEY/2)], C_ff[i-1][1]};
                assign D_nx = {D_ff[i-1][2:(USED_KEY/2)], D_ff[i-1][1]};
            end
        end else begin
