module delete_node_binary_search_tree #(
    parameter DATA_WIDTH = 16,         // Width of the data (of a single element)
    parameter ARRAY_SIZE = 5          // Maximum number of elements in the BST
) (

    input clk,                                  // Clock signal
    input reset,                                // Reset signal
    input reg start,                            // Start signal to initiate the search
    input reg [DATA_WIDTH-1:0] delete_key,      // Key to delete in the BST
    input reg [$clog2(ARRAY_SIZE):0] root,      // Root node of the BST
    input reg [ARRAY_SIZE*DATA_WIDTH-1:0] keys, // Node keys in the BST
    input reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_child,           // Left child pointers
    input reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_child,           // Right child pointers
    output reg [ARRAY_SIZE*DATA_WIDTH-1:0] modified_keys,                    // Node keys in the BST
    output reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] modified_left_child,  // Left child pointers
    output reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] modified_right_child, // Right child pointers
    output reg complete_deletion,         // Signal indicating search completion
    output reg delete_invalid            // Signal indicating invalid search
);
                                                                                                                                       
    // Parameters for FSM states
    parameter S_IDLE = 3'b000,                   // Idle state
              S_INIT = 3'b001,                   // Initialization state
              S_SEARCH_LEFT = 3'b010,            // Search in left subtree
              S_SEARCH_RIGHT = 3'b011,           // Search in both left and right subtrees
              S_DELETE = 3'b100,                 // Delete a node
              S_DELETE_COMPLETE = 3'b101,        // Complete deletion
              S_FIND_INORDER_SUCCESSOR = 3'b110; // State to find inorder successor

   
    // Registers to store the current FSM state
    reg [2:0] delete_state;

    // Variables to manage traversal
    reg found;                                 // Indicates if the key is found

    // Stacks for managing traversal of left and right subtrees
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_stack;  // Stack for left subtree traversal
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_stack; // Stack for right subtree traversal
    reg [$clog2(ARRAY_SIZE)-1:0] sp_left;         // Stack pointer for left subtree
    reg [$clog2(ARRAY_SIZE)-1:0] sp_right;        // Stack pointer for right subtree

    // Pointers for the current nodes in left and right subtrees
    reg [$clog2(ARRAY_SIZE):0] current_left_node;  // Current node in the left subtree
    reg [$clog2(ARRAY_SIZE):0] current_right_node; // Current node in the right subtree
    reg [$clog2(ARRAY_SIZE):0] current_node;       // Current node

    // Integer for loop iterations
    integer i, j;
    reg [$clog2(ARRAY_SIZE):0] null_node;

    // Registers for inorder successor search
    reg [$clog2(ARRAY_SIZE):0] min_node;       // Inorder successor node

    // The INVALID pointer value used in comparisons.
    localparam [($clog2(ARRAY_SIZE)+1)-1:0] INVALID = {($clog2(ARRAY_SIZE)+1){1'b1}};
    localparam [DATA_WIDTH-1:0] INVALID_KEY = {DATA_WIDTH{1'b1}};

     // FSM for inorder successor search
    reg inorder_search_active;                 // Flag to activate inorder successor search

    // Always block triggered on the rising edge of the clock or reset signal
    always @(posedge clk or posedge reset) begin
         reg [$clog2(ARRAY_SIZE):0] lchild, rchild;
        if (reset) begin
            // Reset all states and variables
            delete_state <= S_IDLE;  // Set state to IDLE
            found <= 0;              // Reset found flag
            complete_deletion <= 0;     // Reset complete_deletion signal
            sp_left <= 0;            // Reset left stack pointer
            sp_right <= 0;           // Reset right stack pointer
            delete_invalid <= 0;     // Set invalid_key to 0
            inorder_search_active <= 0;           
            // Clear the stacks
            for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                left_stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                right_stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                modified_left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                modified_right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                modified_keys[i*DATA_WIDTH +: DATA_WIDTH] <= INVALID_KEY;
            end

        end else begin
            // Main FSM logic
            case (delete_state)
                S_IDLE: begin
                    // Reset intermediate variables
                     for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                        left_stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        right_stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        modified_left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        modified_right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        modified_keys[i*DATA_WIDTH +: DATA_WIDTH] <= INVALID_KEY;
                    end
                    complete_deletion <= 0;
                    delete_invalid <= 0;
                    inorder_search_active <= 0;
                    if (start) begin
                        // Start the search
                        sp_left <= 0;
                        sp_right <= 0;
                        found <= 0;
                        delete_state <= S_INIT; // Move to INIT state
                    end
                end

                S_INIT: begin
                    if (root != {($clog2(ARRAY_SIZE)+1){1'b1}}) begin
                        // Compare the delete key with the root key
                        if (delete_key == keys[root*DATA_WIDTH +: DATA_WIDTH]) begin
                            found <= 1;
                            current_node <= 0;
                            delete_state <= S_DELETE; // Move to complete search state
                        end else if (keys[0*DATA_WIDTH +: DATA_WIDTH] > delete_key) begin // Else if the first key in the keys array is greater than the delete key
                            delete_state <= S_SEARCH_LEFT;
                            current_left_node <= left_child[root*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];    // Set current left node pointer from the root's left child
                        end else begin
                            current_left_node <= left_child[root*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];    // Set current left node pointer from the root's left child
                            current_right_node <= right_child[root*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];  // Set current right node pointer from the root's right child
                            delete_state <= S_SEARCH_RIGHT; // Search in both left and right subtrees
                        end
                    end else begin
                        delete_invalid <= 1;
                        complete_deletion <= 0;
                        delete_state <= S_IDLE;
                    end
                end

                S_SEARCH_LEFT: begin
                    // Traverse the left subtree
                    if (current_left_node != {($clog2(ARRAY_SIZE)+1){1'b1}}) begin                // If left traversal is not finished and the current left node is valid
                        left_stack[sp_left*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= current_left_node;  // Push the current left node index onto the left stack
                        sp_left <= sp_left + 1;
                        current_left_node <= left_child[current_left_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];  // Move to the left child of the current node
                        if (delete_key == keys[current_left_node*DATA_WIDTH +: DATA_WIDTH]) begin    // If the key at the retrieved node matches the search key
                            found <= 1;
                            current_node <= current_left_node;  
                            delete_state <= S_DELETE; // Move to complete search state
                        end
                    end else if (sp_left > 0) begin
                        sp_left <= sp_left - 1;
                        current_left_node <= right_child[left_stack[(sp_left - 1)*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)]*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];   // Move to the right child of the popped node for further traversal
                    end else begin
                        if (found == 1) begin
                            delete_state <= S_DELETE; // Move to complete search state
                        end else begin
                            delete_invalid <= 1;
                            complete_deletion <= 0;
                            delete_state <= S_IDLE;
                        end
                    end
                end

                S_SEARCH_RIGHT: begin
                    if (current_right_node != {($clog2(ARRAY_SIZE)+1){1'b1}}) begin
                        right_stack[sp_right*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= current_right_node;
                        sp_right <= sp_right + 1;
                        current_right_node <= left_child[current_right_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)]; // Move to left child of the current right node
                        if (delete_key == keys[current_right_node*DATA_WIDTH +: DATA_WIDTH]) begin
                            current_node <= current_right_node;
                            found <= 1;
                            delete_state <= S_DELETE;  
                        end
                    end else if (sp_right > 0) begin
                        sp_right <= sp_right - 1;
                        current_right_node <= right_child[right_stack[(sp_right - 1)*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)]*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)]; // Move to right child of the popped node
                    end else begin
                        if (found == 1) begin
                            delete_state <= S_DELETE; // Move to complete search state
                        end else begin
                            delete_invalid <= 1;
                            complete_deletion <= 0;
                            delete_state <= S_IDLE;
                        end
                    end
                end

                S_DELETE: begin
                    // First, load the left and right child indices of the node.
                    modified_keys <= keys;     //if not copied here then will give buggy output with only valid values with the moddified tree without the original tree values
                    modified_left_child <= left_child;
                    modified_right_child <= right_child;

                    rchild = right_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];
                    lchild = left_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];

                    if (left_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] == INVALID
                                    && right_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] != INVALID) begin
                        // Node has only right child
                        // Replace the current node's key and pointers with those of its right child.
                        modified_keys[current_node*DATA_WIDTH +: DATA_WIDTH] <= keys[rchild*DATA_WIDTH +: DATA_WIDTH];
                        modified_left_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= left_child[rchild*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];
                        modified_right_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= right_child[rchild*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];
                        null_node <= rchild;
                        delete_state <= S_DELETE_COMPLETE;
                    end
                    else if (right_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] == INVALID
                                && left_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] != INVALID) begin
                        // Node has only left child.
                        modified_keys[current_node*DATA_WIDTH +: DATA_WIDTH] <= keys[lchild*DATA_WIDTH +: DATA_WIDTH];
                        modified_left_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= left_child[lchild*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];
                        modified_right_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= right_child[lchild*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];
                        null_node <= lchild;
                        delete_state <= S_DELETE_COMPLETE;
                    end
                    else if (right_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] == INVALID    //Will give bug 'x' is both condition set to != INVAALID
                                && left_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] == INVALID) begin
                        // Node has no right or left child
                        null_node <= current_node;
                        delete_state <= S_DELETE_COMPLETE;
                    end
                    else begin
                        // Node has two children.
                        // Start finding the inorder successor.
                        min_node <= rchild;
                        inorder_search_active <= 1;
                        delete_state <= S_FIND_INORDER_SUCCESSOR;
                        
                    end
                end

                S_FIND_INORDER_SUCCESSOR: begin
                    if (inorder_search_active) begin
                        if (left_child[min_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] != INVALID) begin
                            min_node <= left_child[min_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)]; // Move to the left child
                        end else begin
                            // Copy the inorder successor's key into the current node.
                            modified_keys[current_node*DATA_WIDTH +: DATA_WIDTH] <= keys[min_node*DATA_WIDTH +: DATA_WIDTH];

                            // Delete the inorder successor by replacing it with its right child.
                            if (right_child[min_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)]!= INVALID) begin
                                modified_keys[min_node*DATA_WIDTH +: DATA_WIDTH] <= keys[right_child[min_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)]*DATA_WIDTH +: DATA_WIDTH];
                                modified_right_child[min_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= right_child[right_child[min_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)]*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];
                                modified_left_child[min_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= left_child[right_child[min_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)]*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];
                                null_node <= right_child[min_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];
                            end else begin
                                null_node <= min_node;
                            end

                            delete_state <= S_DELETE_COMPLETE;
                            inorder_search_active <= 0;
                        end
                    end

                end

                S_DELETE_COMPLETE:begin
                    modified_keys[null_node*DATA_WIDTH +: DATA_WIDTH] <= INVALID_KEY;
                    modified_left_child[null_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= INVALID;
                    modified_right_child[null_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= INVALID;
 
                    for (j=0; j < ARRAY_SIZE; j++) begin
                        if (modified_left_child[j*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] == null_node) begin  //Buggy output if instead of modified child the original child is checked
                            modified_left_child[j*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= INVALID;
                        end
                        if (modified_right_child[j*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] == null_node) begin
                            modified_right_child[j*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= INVALID;
                        end
                    end
                    delete_state <= S_IDLE;
                    complete_deletion <= 1;
                end

                default: begin
                    delete_state <= S_IDLE; // Default to IDLE state
                end
            endcase
        end
    end

endmodule

context/rtl/binary_search_tree_sort_cons:
module binary_search_tree_sort_construct #(
    parameter DATA_WIDTH = 16,
    parameter ARRAY_SIZE = 5
) (
    input clk,
    input reset,
    input reg [ARRAY_SIZE*DATA_WIDTH-1:0] data_in, // Input data to be sorted
    input start,
    output reg [ARRAY_SIZE*DATA_WIDTH-1:0] sorted_out, // Sorted output
    output reg done
);

    // Parameters for top-level FSM states
    parameter IDLE = 2'b00, BUILD_TREE = 2'b01, SORT_TREE = 2'b10;

    // Parameters for nested FSM states (Build Tree)
    parameter INIT = 2'b00, INSERT = 2'b01, TRAVERSE = 2'b10, COMPLETE = 2'b11;

    // Parameters for nested FSM states (Sort Tree)
    parameter S_INIT = 2'b00, S_TRAVERSE_LEFT = 2'b01, S_PROCESS_NODE = 2'b10, S_TRAVERSE_RIGHT = 2'b11;

    // Registers for FSM states
    reg [1:0] top_state, build_state, sort_state;

    // BST representation
    reg [ARRAY_SIZE*DATA_WIDTH-1:0] data_in_copy;
    reg [ARRAY_SIZE*DATA_WIDTH-1:0] temp_out;
    reg [ARRAY_SIZE*DATA_WIDTH-1:0] keys; // Array to store node keys
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_child; // Left child pointers
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_child; // Right child pointers
    reg [$clog2(ARRAY_SIZE):0] root; // Root node pointer
    reg [$clog2(ARRAY_SIZE):0] next_free_node; // Pointer to the next free node

    // Stack for in-order traversal
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] stack; // Stack for traversal
    reg [$clog2(ARRAY_SIZE):0] sp; // Stack pointer

    // Working registers
    reg [$clog2(ARRAY_SIZE):0] current_node; // Current node being processed
    reg [$clog2(ARRAY_SIZE):0] input_index; // Index for input data
    reg [$clog2(ARRAY_SIZE):0] output_index; // Index for output data
    reg [DATA_WIDTH-1:0] temp_data; // Temporary data register

    // Initialize all variables
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all states and variables
            top_state <= IDLE;
            build_state <= INIT;
            sort_state <= S_INIT;
            root <= {($clog2(ARRAY_SIZE)+1){1'b1}}; // Null pointer
            next_free_node <= 0;
            sp <= 0;
            input_index <= 0;
            output_index <= 0;
            done <= 0;

            // Clear tree arrays
            for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                keys[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}}; 
                right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                temp_out[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                sorted_out[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
            end

        end else begin
            case (top_state)
                IDLE: begin
                    done <= 0;
                    input_index <= 0;
                    output_index <= 0; 
                    root <= {($clog2(ARRAY_SIZE)+1){1'b1}}; ; // Null pointer
                    next_free_node <= 0;
                    sp <= 0;
                    for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                        keys[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                        left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}}; 
                        right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        temp_out[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                        sorted_out[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                    end
                    if (start) begin
                        // Load input data into input array
                        top_state <= BUILD_TREE;
                        build_state <= INIT;
                        data_in_copy <= data_in;
                    end
                end
                BUILD_TREE: begin
                    case (build_state)
                        INIT: begin
                            if (input_index < ARRAY_SIZE) begin
                                temp_data <= data_in_copy[input_index*DATA_WIDTH +: DATA_WIDTH]; 
                                input_index <= input_index + 1;
                                build_state <= INSERT;
                            end else begin
                                build_state <= COMPLETE;
                            end
                        end

                        INSERT: begin
                            if (root == {($clog2(ARRAY_SIZE)+1){1'b1}}) begin
                                // Tree is empty, insert at root
                                root <= next_free_node;
                                keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                                next_free_node <= next_free_node + 1; 
                                build_state <= INIT;
                            end else begin
                                // Traverse the tree to find the correct position
                                current_node <= root; 
                                build_state <= TRAVERSE;
                            end
                        end
                        
                        TRAVERSE: begin      
                            if ((temp_data < keys[current_node*DATA_WIDTH +: DATA_WIDTH])) begin
                                if (left_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] == {($clog2(ARRAY_SIZE)+1){1'b1}}) begin 
                                    left_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= next_free_node; 
                                    keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                                    next_free_node <= next_free_node + 1;
                                    build_state <= INIT;
                                end else begin
                                    current_node <= left_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)]; 
                                end
                            end else begin
                                if (right_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] == {($clog2(ARRAY_SIZE)+1){1'b1}}) begin 
                                    right_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= next_free_node; 
                                    keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data; 
                                    next_free_node <= next_free_node + 1;
                                    build_state <= INIT;
                                end else begin
                                    current_node <= right_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)]; 
                                end
                            end
                        end
                        COMPLETE: begin
                            // Tree construction complete
                            top_state <= SORT_TREE;
                            sort_state <= S_INIT;
                        end
                    endcase
                end

                SORT_TREE: begin
                    case (sort_state)
                        S_INIT: begin
                            
                            if (root != {($clog2(ARRAY_SIZE)+1){1'b1}}) begin 
                                current_node <= root; // Start from the root node
                                sp <= 0;
                                sort_state <= S_TRAVERSE_LEFT;
                            end
                        end

                        S_TRAVERSE_LEFT: begin
                            if (current_node != {($clog2(ARRAY_SIZE)+1){1'b1}}) begin
                                stack[sp*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= current_node;
                                sp <= sp + 1;
                                current_node <= left_child[current_node*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];
                            end else begin
                                sort_state <= S_PROCESS_NODE;
                            end
                        end

                        S_PROCESS_NODE: begin
                            if (sp > 0) begin
                                sp <= sp - 1;
                                current_node <= stack[(sp-1)*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)];
                                output_index <= output_index + 1; 
                                temp_out[output_index*DATA_WIDTH +: DATA_WIDTH] <= keys[stack[($unsigned(sp)-1)*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)]*DATA_WIDTH +: DATA_WIDTH]; // Output the key
                                sort_state <= S_TRAVERSE_RIGHT;
                            end else begin
                                done <= 1; // All nodes processed
                                sort_state <= S_INIT;
                                top_state <= IDLE;
                                sorted_out <= temp_out;
                            end
                        end

                        S_TRAVERSE_RIGHT: begin
                            current_node <= right_child[current_node*($clog2(ARRAY_SIZE)+1) +:($clog2(ARRAY_SIZE)+1)];
                            sort_state <= S_TRAVERSE_LEFT;
                        end
                    endcase    
                end

                default: begin
                    top_state <= IDLE; // Default behavior for top-level FSM
                end
            endcase
        end
    end
endmodule

context/rtl/clock_estimator.sv:
module clock_estimator (
    input  logic         clk_sys,        // Reference clock
    input  logic         clk_test,       // Clock to be estimated
    input  logic         rst_n,          // Active low reset signal
    input  logic         enable,         // Enable pulse
    input  logic [31:0]  count_ref,      // Static count reference value
    output logic [31:0]  o_clock_est,    // Number of edges counted
    output logic         o_irq           // Interrupt signal
);

    // Counters and control signals
    logic [31:0] ref_counter;   // Counter for reference clock cycles
    logic [31:0] edge_counter;  // Counter for detected test clock edges
    logic        counting;      // Indicates counting operation is in progress
    // Removed unused signal "clk_in_prev"
    logic [2:0]  clk_test_cdc;   // Clock domain crossing synchronizer register
    logic        tst_posedge;    // Detected rising edge after synchronization

    // Synchronize test clock into the reference clock domain
    always_ff @(posedge clk_sys or negedge rst_n) begin
      if (!rst_n)
        clk_test_cdc <= 3'b0;  // Use a 3-bit zero value
      else
        clk_test_cdc <= { clk_test_cdc[1:0], clk_test };
    end

    // Start counting when enable is asserted and stop when ref_counter reaches count_ref - 1
    always_ff @(posedge clk_sys or negedge rst_n) begin
      if (!rst_n)
        counting <= 1'b0;
      else if (enable && !counting)
        counting <= 1'b1;
      else if (ref_counter >= (count_ref - 1))
        counting <= 1'b0;
    end

    // Generate a pulse when a rising edge is detected in the synchronized test clock
    always_ff @(posedge clk_sys or negedge rst_n) begin
      if (!rst_n)
        tst_posedge <= 1'b0;
      else
        tst_posedge <= (clk_test_cdc[2:1] == 2'b01);
    end

    // Reference counter: count clock cycles while counting is active
    always_ff @(posedge clk_sys or negedge rst_n) begin
      if (!rst_n)
        ref_counter <= 32'b0;
      else if (counting)
        ref_counter <= ref_counter + 1;
      else
        ref_counter <= 32'b0;    
    end

    // Edge counter: count rising edges detected on the test clock
    always_ff @(posedge clk_sys or negedge rst_n) begin
      if (!rst_n)
        edge_counter <= 32'b0;
      else if (counting && tst_posedge)
        edge_counter <= edge_counter + 1;
      else if (!counting)
        edge_counter <= 32'b0;
    end

    // Output logic: when counting completes, latch the edge count and raise the interrupt.
    always_ff @(posedge clk_sys or negedge rst_n) begin
      if (!rst_n) begin      
        o_clock_est <= 32'b0;
        o_irq       <= 1'b0;
      end
      else if (enable && !counting) begin
        // When not counting, ensure outputs are reset.
        o_clock_est <= 32'b0;
        o_irq       <= 1'b0;
      end
      else if (counting && (ref_counter >= count_ref - 1)) begin
        // Counting complete: latch the edge counter value and assert interrupt.
        o_clock_est <= edge_counter;
        o_irq       <= 1'b1;
      end
      else begin
        // Default case: deassert interrupt.
        o_irq       <= 1'b0;
      end
    end

endmodule

context/rtl/fifo_buffer.sv:
module fifo_buffer #(
  parameter int unsigned NUM_OF_REQS = 2,
  parameter bit          ResetAll      = 1'b0
) (
  input  logic                clk_i,
  input  logic                rst_i,

  input  logic                clear_i,   
  output logic [NUM_OF_REQS-1:0] busy_o,

  input  logic                in_valid_i,
  input  logic [31:0]         in_addr_i,
  input  logic [31:0]         in_rdata_i,
  input  logic                in_err_i,

  output logic                out_valid_o,
  input  logic                out_ready_i,
  output logic [31:0]         out_addr_o,
  output logic [31:0]         out_rdata_o,
  output logic                out_err_o,
  output logic                out_err_plus2_o
);

  localparam int unsigned FIFO_DEPTH = NUM_OF_REQS + 1;

  logic [31:0] rdata_d [0:FIFO_DEPTH-1];
  logic [31:0] rdata_q [0:FIFO_DEPTH-1];
  logic [FIFO_DEPTH-1:0]         err_d,     err_q;
  logic [FIFO_DEPTH-1:0]         valid_d,   valid_q;
  logic [FIFO_DEPTH-1:0]         lowest_free_entry;
  logic [FIFO_DEPTH-1:0]         valid_pushed, valid_popped;
  logic [FIFO_DEPTH-1:0]         entry_en;

  logic                     pop_fifo;
  logic         [31:0]      rdata, rdata_unaligned;
  logic                     err,   err_unaligned, err_plus2;
  logic                     valid, valid_unaligned;

  logic                     aligned_is_compressed, unaligned_is_compressed;

  logic                     addr_incr_two;
  logic [31:1]              instr_addr_next;
  logic [31:1]              instr_addr_d, instr_addr_q;
  logic                     instr_addr_en;
  logic                     unused_addr_in;

  assign rdata = valid_q[1] ? rdata_q[1] : in_rdata_i;
  assign err   = valid_q[1] ? err_q[1]   : in_err_i;
  assign valid = valid_q[1] | in_valid_i;

  assign rdata_unaligned = valid_q[1] ? {rdata_q[1][15:0], rdata[31:16]} :
                                        {in_rdata_i[15:0], rdata[31:16]};

  assign err_unaligned   = valid_q[1] ? ((err_q[1] & ~unaligned_is_compressed) | err_q[0]) :
                                        ((valid_q[0] & err_q[0]) |
                                         (in_err_i & (~valid_q[0] | ~unaligned_is_compressed)));

  assign err_plus2       = valid_q[0] ? (err_q[0] & ~err_q[0]) :
                                        (in_err_i & valid_q[1] & ~err_q[1]);

  assign valid_unaligned = valid_q[1] ? 1'b1 :
                                        (valid_q[0] & in_valid_i);

  assign unaligned_is_compressed = (rdata[17:16] != 2'b11);
  assign aligned_is_compressed   = (rdata[1:0]   != 2'b11);

  always @(*) begin
    if (out_addr_o[1]) begin
      out_rdata_o     = rdata_unaligned;
      out_err_o       = err_unaligned;
      out_err_plus2_o = err_plus2;
      if (unaligned_is_compressed) begin
        out_valid_o = valid;
      end else begin
        out_valid_o = valid_unaligned;
      end
    end else begin
      out_rdata_o     = rdata;
      out_err_o       = err;
      out_err_plus2_o = 1'b1;
      out_valid_o     = valid;
    end
  end

  assign instr_addr_en   = clear_i | (out_ready_i & out_valid_o);
  assign addr_incr_two   = instr_addr_q[1] ? unaligned_is_compressed :
                                               aligned_is_compressed;

  assign instr_addr_next = (instr_addr_q[31:1] +
                            {29'd0, ~addr_incr_two, addr_incr_two});

  assign instr_addr_d    = clear_i ? in_addr_i[31:1] : instr_addr_next;

  if (ResetAll) begin : g_instr_addr_ra
    always_ff @(posedge clk_i or negedge rst_i) begin
      if (!rst_i) begin
        instr_addr_q <= '0;
      end else if (instr_addr_en) begin
        instr_addr_q <= instr_addr_q;
      end
    end
  end else begin : g_instr_addr_nr
    always_ff @(posedge clk_i) begin
      if (instr_addr_en) begin
        instr_addr_q <= instr_addr_d;
      end
    end
  end

  assign out_addr_o = {instr_addr_q, 1'b0};
  assign unused_addr_in = in_addr_i[0];

  assign busy_o = valid_q[FIFO_DEPTH-1:FIFO_DEPTH-NUM_OF_REQS];
  assign pop_fifo = out_ready_i & out_valid_o;

  for (genvar i = 0; i < (FIFO_DEPTH - 1); i++) begin : g_fifo_next
    if (i == 0) begin : g_ent0
      assign lowest_free_entry[i] = ~valid_q[i];
    end else begin : g_ent_others
      assign lowest_free_entry[i] = ~valid_q[i] & valid_q[i-1];
    end

    assign valid_pushed[i] = (in_valid_i & lowest_free_entry[i]) | valid_q[i];
    assign valid_popped[i] = pop_fifo ? valid_pushed[i+1] : valid_pushed[i];
    assign valid_d[i]      = valid_popped[i] & ~clear_i;
    assign entry_en[i]     = (valid_pushed[i+1] & pop_fifo) |
                             (in_valid_i & lowest_free_entry[i] & ~pop_fifo);
    assign rdata_d[i]      = valid_q[i+1] ? rdata_q[i+1] : in_rdata_i;
    assign err_d[i]        = valid_q[i+1] ? err_q[i+1]   : in_err_i;
  end

  assign lowest_free_entry[FIFO_DEPTH-1] = ~valid_q[FIFO_DEPTH-1] & valid_q[FIFO_DEPTH-2];
  assign valid_pushed[FIFO_DEPTH-1]      = valid_q[FIFO_DEPTH-1] | (in_valid_i & lowest_free_entry[FIFO_DEPTH-1]);
  assign valid_popped[FIFO_DEPTH-1]      = pop_fifo ? 1'b0 : valid_pushed[FIFO_DEPTH-1];
  assign valid_d[FIFO_DEPTH-1]           = valid_popped[FIFO_DEPTH-1] & ~clear_i;
  assign entry_en[FIFO_DEPTH-1]          = in_valid_i & lowest_free_entry[FIFO_DEPTH-1];
  assign rdata_d[FIFO_DEPTH-1]           = in_rdata_i;
  assign err_d[FIFO_DEPTH-1]             = in_err_i;

  always_ff @(posedge clk_i or negedge rst_i) begin
    if (!rst_i) begin
      valid_q <= '0;
    end else begin
      valid_q <= valid_d;
    end
  end

  for (genvar i = 0; i < FIFO_DEPTH; i++) begin : g_fifo_regs
    if (ResetAll) begin : g_rdata_ra
      always_ff @(posedge clk_i or negedge rst_i) begin
        if (!rst_i) begin
          rdata_q[i] <= '0;
          err_q[i]   <= '0;
        end else if (entry_en[i]) begin
          rdata_q[i] <= rdata_d[i];
          err_q[i]   <= err_d[i];
        end
      end
    end else begin : g_rdata_nr
      always_ff @(posedge clk_i) begin
        if (entry_en[i]) begin
          rdata_q[i] <= rdata_d[i];
          err_q[i]   <= err_d[i];
        end
      end
    end
  end
endmodule

context/verif/tb_fifo_buffer.sv:
`timescale 1ns/1ps

module tb_fifo_buffer;

  
  parameter int unsigned NUM_OF_REQS = 2;
  parameter bit          ResetAll    = 1'b0; 

  
  logic                clk_i;
  logic                rst_i;
  logic                clear_i;
  logic [NUM_OF_REQS-1:0] busy_o;

  logic                in_valid_i;
  logic [31:0]         in_addr_i;
  logic [31:0]         in_rdata_i;
  logic                in_err_i;

  logic                out_valid_o;
  logic                out_ready_i;
  logic [31:0]         out_addr_o;
  logic [31:0]         out_rdata_o;
  logic                out_err_o;
  logic                out_err_plus2_o;

  
  fifo_buffer #(
    .NUM_OF_REQS(NUM_OF_REQS),
    .ResetAll(ResetAll)
  ) dut (
    .clk_i(clk_i),
    .rst_i(rst_i),
    .clear_i(clear_i),
    .busy_o(busy_o),
    .in_valid_i(in_valid_i),
    .in_addr_i(in_addr_i),
    .in_rdata_i(in_rdata_i),
    .in_err_i(in_err_i),
    .out_valid_o(out_valid_o),
    .out_ready_i(out_ready_i),
    .out_addr_o(out_addr_o),
    .out_rdata_o(out_rdata_o),
    .out_err_o(out_err_o),
    .out_err_plus2_o(out_err_plus2_o)
  );

  initial begin
    clk_i = 0;
    forever #5 clk_i = ~clk_i;
  end

  initial begin
    rst_i = 0;
    #20;
    rst_i = 1;
  end

  initial begin
    clear_i     = 0;
    in_valid_i  = 0;
    in_addr_i   = 32'h0000_0000;
    in_rdata_i  = 32'h0;
    in_err_i    = 0;
    out_ready_i = 0;
    
    @(posedge rst_i);
    #10;
    
    $display("\n*** Test 1: Clear FIFO (Aligned PC) ***");
    clear_i   = 1;
    in_addr_i = 32'h0000_0000;
    #10;
    clear_i = 0;
    #10;
    
    $display("\n*** Test 2: Single Instruction Fetch (Aligned) ***");
    in_valid_i = 1;
    in_rdata_i = 32'h8C218363;
    in_err_i   = 0;
    #10;
    in_valid_i = 0;
    #10;
    
    out_ready_i = 1;
    #10;
    out_ready_i = 0;
    #10;
    
    $display("\n*** Test 3: FIFO Depth Test ***");
    in_valid_i = 1;
    in_rdata_i = 32'h6C2183E3;
    in_err_i   = 0;
    #10;
    in_rdata_i = 32'h926CF16F;
    #10;
    in_valid_i = 0;
    #10;
    
    out_ready_i = 1;
    repeat (3) begin
      #10;
    end
    out_ready_i = 0;
    #10;
    
    $display("\n*** Test 4: Unaligned Instruction Fetch ***");
    clear_i   = 1;
    in_addr_i = 32'h0000_0002;
    #10;
    clear_i = 0;
    #10;
    
    in_valid_i = 1;
    in_rdata_i = 32'hF63101E7;
    in_err_i   = 0;
    #10;
    
    in_rdata_i = 32'h763101E7;
    #10;
    in_valid_i = 0;
    #10;
    
    out_ready_i = 1;
    repeat (3) begin
      #10;
    end
    out_ready_i = 0;
    #10;
    
    $display("\n*** Test 5: Error Handling ***");
    clear_i   = 1;
    in_addr_i = 32'h0000_0000;
    #10;
    clear_i = 0;
    #10;
    
    in_valid_i = 1;
    in_rdata_i = 32'h4840006F;
    in_err_i   = 1;
    #10;
    in_valid_i = 0;
    #10;
    
    out_ready_i = 1;
    #10;
    out_ready_i = 0;
    #10;
    
    $display("\n*** End of Simulation ***");
    $finish;
  end

  initial begin
    $display("Time\tclear in_valid in_addr    in_rdata      in_err | out_valid out_addr    out_rdata     out_err out_err_plus2 | busy");
    $monitor("%0t\t%b      %b      %h   %h    %b    | %b      %h  %h   %b    %b    | %h",
             $time, clear_i, in_valid_i, in_addr_i, in_rdata_i, in_err_i,
             out_valid_o, out_addr_o, out_rdata_o, out_err_o, out_err_plus2_o,
             busy_o);
  end

endmodule

context/verif/tb_direct_map_cache.sv:
`timescale 1ns/1ps

module tb_direct_map_cache;

    // Parameters
    parameter CACHE_SIZE = 256;               // Number of cache lines
    parameter DATA_WIDTH = 16;                // Width of data
    parameter TAG_WIDTH = 5;                  // Width of the tag
    parameter OFFSET_WIDTH = 3;               // Width of the offset

    // Inputs
    reg enable;                               // Enable signal for cache
    reg [7:0] index;                          // 8 bits for indexing into the cache
    reg [OFFSET_WIDTH-1:0] offset;            // 3 bits for offset
    reg comp;                                 // Compare signal
    reg write;                                // Write signal
    reg [TAG_WIDTH-1:0] tag_in;               // Tag input
    reg [DATA_WIDTH-1:0] data_in;             // Data input
    reg valid_in;                             // Valid input for cache line
    reg clk;                                  // Clock signal
    reg rst;                                  // Reset signal
    reg [DATA_WIDTH-1:0] data;                // Data variable for tasks

    // Outputs
    wire hit;                                 // Hit indication
    wire dirty;                               // Dirty state indication
    wire [TAG_WIDTH-1:0] tag_out;             // Output tag of the cache line
    wire [DATA_WIDTH-1:0] data_out;           // Output data from the cache line
    wire valid;                               // Valid state output
    wire error;                               // Error indication

    integer i;                                

    // Instantiate the cache
    direct_map_cache #(
                                    .CACHE_SIZE(CACHE_SIZE),
                                    .DATA_WIDTH(DATA_WIDTH),
                                    .TAG_WIDTH(TAG_WIDTH),
                                    .OFFSET_WIDTH(OFFSET_WIDTH)
                                   )
			                   uut (
                                    .enable(enable),
                                    .index(index),
                                    .offset(offset),
                                    .comp(comp),
                                    .write(write),
                                    .tag_in(tag_in),
                                    .data_in(data_in),
                                    .valid_in(valid_in),
                                    .clk(clk),
                                    .rst(rst),
                                    .hit(hit),
                                    .dirty(dirty),
                                    .tag_out(tag_out),
                                    .data_out(data_out),
                                    .valid(valid),
                                    .error(error)
                                   );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;  // 10 ns period
    end

    // Test procedure
    initial begin
        // Initialize inputs
        enable = 0;
        rst = 1;
        @(posedge clk);
        rst = 0;
        @(posedge clk); 

        // Enable cache
        enable = 1;
        // Pseudo-Random Replacement Condition Checking
        // Fill the cache to trigger replacement
        write_task(8'h02, 3'b000, 5'b00000, 1'b1,1'b1);
        read_task(8'h02, 3'b000, 5'b00000, 1'b1);
        write_task(8'h02, 3'b000, 5'b00001, 1'b1,1'b1);
        read_task(8'h02, 3'b000, 5'b00001, 1'b1);
        write_task(8'h02, 3'b000, 5'b00010, 1'b1,1'b1);
        read_task(8'h02, 3'b000, 5'b00010, 1'b1);
        write_task(8'h02, 3'b000, 5'b00011, 1'b1,1'b1);
        read_task(8'h02, 3'b000, 5'b00011, 1'b1);

        @(posedge clk); 

        // Write to cache without compare
        write_task(8'h00, 3'b000, 5'b00001, 1'b0,1'b1);

	    // Read from cache without compare
        read_task(8'h00, 3'b000, 5'b00001, 1'b0);

        // Write to cache with compare
        write_task(8'h00, 3'b000, 5'b00001, 1'b1,1'b1);

        // Read from cache  with compare
        read_task(8'h00, 3'b000, 5'b00001, 1'b1);

        // Write to cache with out compare 
        write_task(8'h01, 3'b110, 5'b00010, 1'b0,1'b1);

        // Read from cache  with compare
        read_task(8'h01, 3'b110, 5'b00010, 1'b1);

        // Error condition
        write_task(8'h01, 3'b001, 5'b00010, 1'b0,1'b1);      
        @(posedge clk); 
        check_error(3'b001, error);
        // Finalize simulation
        $finish;
    end

    // Task to handle writing to the cache
    task write_task(input [7:0] indx, input [2:0] off, input [4:0] tag, input compr, valid);
        begin
            index = indx;  
            offset = off; 
            tag_in = tag; 
            data_in = $random; 
            valid_in = valid;    
            write = 1'b1;       
            comp = compr; 
            @(posedge clk); 

             // Display after the clock
            $display("\n[WRITE_TASK] @time %0t", $time);
            $display("  -> index=%0d (0x%0h), offset=%0d (0x%0h), tag_in=%b, data_in=%0h",
                      index, index, offset, offset, tag_in, data_in);
            $display("  -> comp=%b, write=%b, valid_in=%b", comp, write, valid_in);
            $display("  -> hit=%b, dirty=%b, tag_out=%b, data_out=%0h, valid=%b, error=%b",
                      hit, dirty, tag_out, data_out, valid, error);
        end
    endtask 

    // Task to handle reading from the cache
    task read_task(input [7:0] indx, input [2:0] off, input [4:0] tag, input compr);
        begin
            index = indx;  
            offset = off; 
            tag_in = tag; 
            comp = compr;
            @(posedge clk);        
            write = 1'b0;
            @(posedge clk);
        
            $display("\n[READ_TASK] @time %0t", $time);
            $display("  -> index=%0d (0x%0h), offset=%0d (0x%0h), tag_in=%b",
                      index, index, offset, offset, tag_in);
            $display("  -> comp=%b, write=%b", comp, write);
            $display("  -> hit=%b, dirty=%b, tag_out=%b, data_out=%0h, valid=%b, error=%b",
                      hit, dirty, tag_out, data_out, valid, error);


            if (data_in !== data_out)
                $display("  -> [Error] Data mismatch! data_in=%0h, data_out=%0h",
                          data_in, data_out);
            else
                $display("  -> [Pass] Data matched.");
            @(posedge clk); 
        end
    endtask

    task check_error(input [2:0] offset_val, input error_signal);
        begin
            if (offset_val[0]) begin
                if (error_signal)
                    $display("  -> [PASS] ERROR correctly asserted for misaligned offset (offset[0]=1)");
                else
                    $display("  -> [FAIL] ERROR was expected for misaligned offset, but not asserted!");
                end else begin
                if (error_signal)
                    $display("  -> [FAIL] ERROR was unexpectedly asserted on aligned offset (offset[0]=0)");
                else
                    $display("  -> [PASS] No error as expected (aligned offset)");
            end
        end
    endtask

    // Waveform dumping for simulation analysis
    initial begin
        $dumpfile("direct_map_cachet.vcd");    // Specify the VCD file for waveform dumping
        $dumpvars(0, tb_direct_map_cache);     // Dump all variables in the testbench
    end
endmodule

context/rtl/elevator_control_system.sv:
/*
 * Elevator Control System
 * 
 * This module implements an FSM-based elevator control system capable of managing multiple floors,
 * handling call requests, and responding to emergency stops. The elevator transitions between 
 * five main states: Idle, Moving Up, Moving Down, Emergency Halt, Door Open. It prioritizes floor requests 
 * based on direction, moving to the highest or lowest requested floor depending on the current direction.
*/
module elevator_control_system #(
    parameter N = 8, //Number of floors
    parameter DOOR_OPEN_TIME_MS = 500 // Door open time in milliseconds
) ( 
    input wire clk,                   // 100MHz clock input
    input wire reset,                 // Active-high reset signal
    input wire [N-1:0] call_requests, // External Floor call requests
    input wire emergency_stop,        // Emergency stop signal
    output wire [$clog2(N)-1:0] current_floor, // Current floor of the elevator
    output reg direction,             // Elevator direction: 1 = up, 0 = down
    output reg door_open,             // Door open signal
    output reg [2:0] system_status    // Elevator system state indicator
);

    typedef enum logic [2:0] {
        IDLE           = 3'b000,
        MOVING_UP      = 3'b001,
        MOVING_DOWN    = 3'b010,
        EMERGENCY_HALT = 3'b011,
        DOOR_OPEN   = 3'b100
    } state_t;

    state_t state, next_state;

// Internal registers
reg [N-1:0] call_requests_internal;   // Internal copy of call requests
reg [$clog2(N)-1:0] max_request;     // Highest requested floor
reg [$clog2(N)-1:0] min_request;    // Lowest requested floor


// Door open time configuration
`ifdef SIMULATION
    localparam CLK_FREQ_MHZ = 100;  // Clock frequency in MHz
    localparam SIM_DOOR_OPEN_TIME_MS = 0.05; // Shorter door open time for simulation
    localparam DOOR_OPEN_CYCLES = (SIM_DOOR_OPEN_TIME_MS * CLK_FREQ_MHZ * 1000); // Door open cycles for simulation   
`else
    // Calculating door open cycles based on time and clock frequency
    localparam CLK_FREQ_MHZ = 100;  // Clock frequency in MHz
    localparam DOOR_OPEN_CYCLES = (DOOR_OPEN_TIME_MS * CLK_FREQ_MHZ * 1000);   // Door open cycles for real implementation
`endif


reg [$clog2(DOOR_OPEN_CYCLES)-1:0] door_open_counter;   // Counter for door open duration


reg [$clog2(N)-1:0] current_floor_reg, current_floor_next=0;

assign current_floor = current_floor_reg;

// FSM state transition
always_ff @(posedge clk or posedge reset) begin
    if(reset)begin
        state <= IDLE;
        system_status <= IDLE;
        current_floor_reg <= 0;
        max_request <= 0;
        min_request <= N-1;        
    end else begin
        state <= next_state;
        system_status <= next_state;
        current_floor_reg <= current_floor_next;
        
        // Calculate max_request and min_request based on active requests
        max_request = 0;
        min_request = N-1;
        for (integer i = 0; i < N; i = i + 1) begin
            if (call_requests_internal[i]) begin
                if (i > max_request) max_request = i;
                if (i < min_request) min_request = i;
            end
        end
    end
end

    always_comb begin
    next_state = state;
    current_floor_next = current_floor_reg;
    
    case(state)
        IDLE:begin
            if(emergency_stop)begin
                next_state = EMERGENCY_HALT;
            end else if(call_requests_internal != 0)begin
                if(max_request > current_floor_reg)begin
                    next_state = MOVING_UP;
                end else if(min_request < current_floor_reg) begin
                    next_state = MOVING_DOWN;
                end
            end
        end

        MOVING_UP: begin
            if(emergency_stop)begin
                next_state = EMERGENCY_HALT;
            end else if(call_requests_internal[current_floor_reg+1]) begin
                current_floor_next = current_floor_reg + 1;
                next_state = DOOR_OPEN;
            end else if(current_floor_reg >= max_request) begin
                // If we reach the highest request, go idle
                next_state = IDLE;
            end else begin
                current_floor_next = current_floor_reg + 1;
                next_state = MOVING_UP;
            end
        end

        MOVING_DOWN: begin
            if(emergency_stop)begin
                next_state = EMERGENCY_HALT;
            end else if(call_requests_internal[current_floor_reg-1]) begin
                current_floor_next = current_floor_reg - 1;
                next_state = DOOR_OPEN;
            end else if(current_floor_reg <= min_request) begin
                // If we reach the lowest request, go idle
                next_state = IDLE;
            end else begin
                current_floor_next = current_floor_reg - 1;
                next_state = MOVING_DOWN;
            end
        end

        EMERGENCY_HALT: begin
            if (!emergency_stop) begin
                next_state = IDLE;
                current_floor_next = 0; // Optionally reset to ground floor
            end
        end
        DOOR_OPEN: begin
            if (door_open_counter == 0) begin
                next_state = IDLE;
            end else begin
                next_state = DOOR_OPEN;
            end
        end
    endcase
end


// Door open control logic
always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        door_open_counter <= 0;
        door_open <= 0;
    end else begin
        if (state == DOOR_OPEN) begin
            if (door_open_counter > 0) begin
                door_open <= 1;
                door_open_counter <= door_open_counter - 1;
            end else begin
                door_open <= 0;
                next_state = IDLE;
            end
        end else begin
            door_open <= 0;
            door_open_counter <= DOOR_OPEN_CYCLES; // Reset door open counter
        end
    end
end

// Call request management
    always_comb begin
    if(reset) begin
        call_requests_internal = 0;
    end else begin
        if(call_requests_internal[current_floor_reg])begin
            call_requests_internal[current_floor_reg] = 0;      // Clear served request
        end
        call_requests_internal = call_requests_internal | call_requests;    // Update requests
    end
end

// Direction control logic
    always_comb begin
        if (reset) direction = 1;
        else if (state == MOVING_UP) direction = 1;
        else if (state == MOVING_DOWN) direction = 0;
        else direction = 1;
    end

endmodule

context/rtl/event_scheduler.sv:
module event_scheduler(
    input clk,
    input reset,
    input add_event,
    input cancel_event,
    input [3:0] event_id,
    input [15:0] timestamp,
    input [3:0] priority_in,
    output reg event_triggered,
    output reg [3:0] triggered_event_id,
    output reg error,
    output reg [15:0] current_time
);

    
    reg [15:0] event_timestamps [15:0];
    reg [3:0]  event_priorities [15:0];
    reg        event_valid      [15:0];
    reg [15:0] tmp_current_time;
    reg [15:0] tmp_event_timestamps [15:0];
    reg [3:0]  tmp_event_priorities [15:0];
    reg        tmp_event_valid [15:0];
    integer i, j;
    integer chosen_event;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_time <= 0;
            event_triggered <= 0;
            triggered_event_id <= 0;
            error <= 0;
            for (i = 0; i < 16; i = i + 1) begin
                event_timestamps[i] <= 0;
                event_priorities[i] <= 0;
                event_valid[i] <= 0;
            end
        end else begin
            tmp_current_time = current_time + 10;
            for (j = 0; j < 16; j = j + 1) begin
                tmp_event_timestamps[j] = event_timestamps[j];
                tmp_event_priorities[j] = event_priorities[j];
                tmp_event_valid[j] = event_valid[j];
            end

            if (add_event) begin
                if (tmp_event_valid[event_id]) begin
                    error <= 1; 
                end else begin
                    tmp_event_timestamps[event_id] = timestamp;
                    tmp_event_priorities[event_id] = priority_in;
                    tmp_event_valid[event_id] = 1;
                    error <= 0;
                end
            end

            if (cancel_event) begin
                if (tmp_event_valid[event_id]) begin
                    tmp_event_valid[event_id] = 0;
                    error <= 0;
                end else begin
                    error <= 1; 
                end
            end

            chosen_event = -1;
            for (j = 0; j < 16; j = j + 1) begin
                if (tmp_event_valid[j] && (tmp_event_timestamps[j] <= tmp_current_time)) begin
                    if ((chosen_event == -1) || (tmp_event_priorities[j] > tmp_event_priorities[chosen_event])) begin
                        chosen_event = j;
                    end
                end
            end

            if (chosen_event != -1) begin
                event_triggered <= 1;
                triggered_event_id <= chosen_event;
                tmp_event_valid[chosen_event] = 0;
            end else begin
                event_triggered <= 0;
            end

            current_time <= tmp_current_time;
            for (j = 0; j < 16; j = j + 1) begin
                event_timestamps[j] <= tmp_event_timestamps[j];
                event_priorities[j] <= tmp_event_priorities[j];
                event_valid[j] <= tmp_event_valid[j];
            end
        end
    end

endmodule

context/verif/tb_event_scheduler.sv:
`timescale 1ns/1ps

module tb_event_scheduler;

  
  reg clk;
  reg reset;
  reg add_event;
  reg cancel_event;
  reg [3:0] event_id;
  reg [15:0] timestamp;
  reg [3:0] priority_in;
  reg modify_event;
  reg [15:0] new_timestamp;
  reg [3:0] new_priority;
  reg recurring_event;
  reg [15:0] recurring_interval;
  wire event_triggered;
  wire [3:0] triggered_event_id;
  wire error;
  wire [15:0] current_time;
  wire [15:0] log_event_time;
  wire [3:0] log_event_id;

  
  event_scheduler dut (
    .clk(clk),
    .reset(reset),
    .add_event(add_event),
    .cancel_event(cancel_event),
    .event_id(event_id),
    .timestamp(timestamp),
    .priority_in(priority_in),
    .modify_event(modify_event),
    .new_timestamp(new_timestamp),
    .new_priority(new_priority),
    .recurring_event(recurring_event),
    .recurring_interval(recurring_interval),
    .event_triggered(event_triggered),
    .triggered_event_id(triggered_event_id),
    .error(error),
    .current_time(current_time),
    .log_event_time(log_event_time),
    .log_event_id(log_event_id)
  );

  
  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  
  task clear_signals;
    begin
      add_event         = 0;
      cancel_event      = 0;
      modify_event      = 0;
      event_id          = 4'b0;
      timestamp         = 16'b0;
      priority_in       = 4'b0;
      new_timestamp     = 16'b0;
      new_priority      = 4'b0;
      recurring_event   = 0;
      recurring_interval= 16'b0;
    end
  endtask

  
  task do_reset;
    begin
      clear_signals;
      reset = 1;
      #12;  
      reset = 0;
      #10;  
    end
  endtask

  
  task wait_for_trigger;
    begin
      wait (event_triggered == 1);
      #1; 
    end
  endtask

  
  initial begin
    $display("Starting Modified Testbench with Correct Sampling...");

    
    do_reset();
    $display("\nTC1: Adding event ID=1 with timestamp=30, priority=2");
    clear_signals;
    event_id    = 4'd1;
    timestamp   = 16'd30;
    priority_in = 4'd2;
    add_event   = 1;
    #10;
    clear_signals;
    wait_for_trigger();
    $display("TC1 Outputs: event_triggered=%0d, triggered_event_id=%0d, error=%0d, current_time=%0d, log_event_time=%0d, log_event_id=%0d",
             event_triggered, triggered_event_id, error, current_time, log_event_time, log_event_id);

    
    do_reset();
    $display("\nTC2: Adding event ID=2 then canceling it");
    clear_signals;
    event_id    = 4'd2;
    timestamp   = 16'd50;
    priority_in = 4'd3;
    add_event   = 1;
    #10;
    clear_signals;
    event_id    = 4'd2;
    cancel_event= 1;
    #10;
    clear_signals;
    repeat (5) #10;
    $display("TC2 Outputs: event_triggered=%0d, triggered_event_id=%0d, error=%0d, current_time=%0d, log_event_time=%0d, log_event_id=%0d",
             event_triggered, triggered_event_id, error, current_time, log_event_time, log_event_id);

    
    do_reset();
    $display("\nTC3: Adding event ID=3 then modifying its timestamp and priority");
    clear_signals;
    event_id    = 4'd3;
    timestamp   = 16'd70;
    priority_in = 4'd1;
    add_event   = 1;
    #10;
    clear_signals;
    event_id       = 4'd3;
    new_timestamp  = 16'd90;
    new_priority   = 4'd4;
    modify_event   = 1;
    #10;
    clear_signals;
    wait_for_trigger();
    $display("TC3 Outputs: event_triggered=%0d, triggered_event_id=%0d, error=%0d, current_time=%0d, log_event_time=%0d, log_event_id=%0d",
             event_triggered, triggered_event_id, error, current_time, log_event_time, log_event_id);

    
    do_reset();
    $display("\nTC4: Adding event ID=4 twice to generate error");
    clear_signals;
    event_id    = 4'd4;
    timestamp   = 16'd40;
    priority_in = 4'd2;
    add_event   = 1;
    #10;
    clear_signals;
    event_id    = 4'd4;
    timestamp   = 16'd60;
    priority_in = 4'd3;
    add_event   = 1;
    #10;
    clear_signals;
    repeat (3) #10;
    $display("TC4 Outputs: event_triggered=%0d, triggered_event_id=%0d, error=%0d, current_time=%0d, log_event_time=%0d, log_event_id=%0d",
             event_triggered, triggered_event_id, error, current_time, log_event_time, log_event_id);

    
    do_reset();
    $display("\nTC5: Attempting to modify non-existent event ID=5 to generate error");
    clear_signals;
    event_id      = 4'd5;
    new_timestamp = 16'd100;
    new_priority  = 4'd5;
    modify_event  = 1;
    #10;
    clear_signals;
    repeat (2) #10;
    $display("TC5 Outputs: event_triggered=%0d, triggered_event_id=%0d, error=%0d, current_time=%0d, log_event_time=%0d, log_event_id=%0d",
             event_triggered, triggered_event_id, error, current_time, log_event_time, log_event_id);

    
    do_reset();
    $display("\nTC6: Attempting to cancel non-existent event ID=6 to generate error");
    clear_signals;
    event_id    = 4'd6;
    cancel_event= 1;
    #10;
    clear_signals;
    repeat (2) #10;
    $display("TC6 Outputs: event_triggered=%0d, triggered_event_id=%0d, error=%0d, current_time=%0d, log_event_time=%0d, log_event_id=%0d",
             event_triggered, triggered_event_id, error, current_time, log_event_time, log_event_id);

    
    do_reset();
    $display("\nTC7: Adding recurring event ID=7 with interval=20");
    clear_signals;
    event_id          = 4'd7;
    timestamp         = 16'd20; 
    priority_in       = 4'd3;
    recurring_event   = 1;
    recurring_interval= 16'd20;
    add_event         = 1;
    #10;
    clear_signals;
    wait_for_trigger(); 
    $display("TC7 (First Trigger) Outputs: event_triggered=%0d, triggered_event_id=%0d, error=%0d, current_time=%0d, log_event_time=%0d, log_event_id=%0d",
             event_triggered, triggered_event_id, error, current_time, log_event_time, log_event_id);
    repeat (2) #10;
    if (event_triggered == 1) begin
      $display("TC7 (Additional Trigger) Outputs: event_triggered=%0d, triggered_event_id=%0d, error=%0d, current_time=%0d, log_event_time=%0d, log_event_id=%0d",
               event_triggered, triggered_event_id, error, current_time, log_event_time, log_event_id);
    end

    
    do_reset();
    $display("\nTC8: Adding event ID=8 and checking log outputs");
    clear_signals;
    event_id    = 4'd8;
    timestamp   = current_time + 10;
    priority_in = 4'd2;
    add_event   = 1;
    #10;
    clear_signals;
    wait_for_trigger();
    $display("TC8 Outputs: event_triggered=%0d, triggered_event_id=%0d, error=%0d, current_time=%0d, log_event_time=%0d, log_event_id=%0d",
             event_triggered, triggered_event_id, error, current_time, log_event_time, log_event_id);

    
    do_reset();
    $display("\nTC9: Adding event ID=9, then modifying and finally canceling it");
    clear_signals;
    event_id    = 4'd9;
    timestamp   = 16'd150;
    priority_in = 4'd2;
    add_event   = 1;
    #10;
    clear_signals;
    event_id       = 4'd9;
    new_timestamp  = 16'd170;
    new_priority   = 4'd4;
    modify_event   = 1;
    #10;
    clear_signals;
    event_id    = 4'd9;
    cancel_event= 1;
    #10;
    clear_signals;
    repeat (3) #10;
    $display("TC9 Outputs: event_triggered=%0d, triggered_event_id=%0d, error=%0d, current_time=%0d, log_event_time=%0d, log_event_id=%0d",
             event_triggered, triggered_event_id, error, current_time, log_event_time, log_event_id);

    
    do_reset();
    $display("\nTC10: Adding events ID=10 and ID=11 concurrently with same timestamp but different priorities");
    clear_signals;
    event_id    = 4'd10;
    timestamp   = current_time + 20;
    priority_in = 4'd2;
    add_event   = 1;
    #1;  
    event_id    = 4'd11;
    timestamp   = current_time + 20;
    priority_in = 4'd5;
    add_event   = 1;
    #10;  
    clear_signals;
    wait_for_trigger();
    $display("TC10 Outputs: event_triggered=%0d, triggered_event_id=%0d, error=%0d, current_time=%0d, log_event_time=%0d, log_event_id=%0d",
             event_triggered, triggered_event_id, error, current_time, log_event_time, log_event_id);


    $display("\nModified Testbench finished.");
    $finish;
  end

endmodule

harness/src/harness_library.py:
import cocotb
from cocotb.triggers import FallingEdge, RisingEdge, Timer
from collections import deque

async def dut_init(dut):
    # iterate all the input signals and initialize with 0
    for signal in dut:
        if signal._type == "GPI_NET":
            signal.value = 0

class EventArray:
    def __init__(self, NS_ROWS=4, NS_COLS=4, NBW_STR=8, NS_EVT=8):
        self.NS_ROWS = NS_ROWS
        self.NS_COLS = NS_COLS
        self.NBW_STR = NBW_STR
        self.NS_EVT  = NS_EVT
        self.reset()

    def reset(self):
        self.reg_bank = [[[0 for _ in range(self.NS_EVT)]
                          for _ in range(self.NS_COLS)]
                         for _ in range(self.NS_ROWS)]
        self.o_data = 0

    def event_update(self, i_event, i_en_overflow):
        total_bits = self.NS_ROWS * self.NS_COLS * self.NS_EVT
        bin_event = bin(i_event)[2:].zfill(total_bits)  # MSB-first

        MAX_VAL = (1 << self.NBW_STR) - 1

        byte_index = 0
        for row in range(self.NS_ROWS):
            for col in range(self.NS_COLS):
                # Calculate flat index for this (row, col)
                flat_index = row * self.NS_COLS + col
                overflow_en = (i_en_overflow >> (flat_index)) & 1

                for evt in range(self.NS_EVT):
                    bit_index = byte_index * self.NS_EVT + evt
                    if bin_event[bit_index] == '1':
                        current_val = self.reg_bank[row][col][self.NS_EVT - 1 - evt]
                        if overflow_en:
                            self.reg_bank[row][col][self.NS_EVT - 1 - evt] = (current_val + 1) & MAX_VAL
                        else:
                            if current_val < MAX_VAL:
                                self.reg_bank[row][col][self.NS_EVT - 1 - evt] += 1
                byte_index += 1


    def read_data(self, bypass, r_addr, col_sel, i_data):
        # Convert i_data to array of NBW_STR slices (MSB to LSB)
        array_i_data = []
        mask = (1 << self.NBW_STR) - 1
        for i in range(self.NS_COLS):
            shift = self.NBW_STR * (self.NS_COLS - 1 - i)
            array_i_data.append((i_data >> shift) & mask)

        selected_row = None

        # Priority decoder tree: walk MSB → LSB, match original behavior
        for row in range(self.NS_ROWS):
            bit = (bypass >> (self.NS_ROWS - 1 - row)) & 1
            if bit == 0:
                selected_row = self.NS_ROWS - 1 - row
                break

        # All bypass bits = 1 → use i_data
        if selected_row is None:
            out_row = array_i_data
        else:
            out_row = [self.reg_bank[selected_row][i][r_addr] for i in range(self.NS_COLS)]

        self.o_data = out_row[col_sel]

context/rtl/column_selector.sv:
module column_selector #(
    parameter NBW_STR = 'd8,
    parameter NBW_COL = 'd2,
    parameter NS_COLS = 'd4
) (
    input  logic [NBW_COL-1:0]           i_col_sel,
    input  logic [(NBW_STR*NS_COLS)-1:0] i_data,
    output logic [NBW_STR-1:0]           o_data
);

// ----------------------------------------
// - Wires/Registers creation
// ----------------------------------------
logic [NBW_STR-1:0] data [0:NS_COLS-1];

// ----------------------------------------
// - Unpack input data
// ----------------------------------------
generate
    for(genvar i = 0; i < NS_COLS; i++) begin : unpack_data
        assign data[i] = i_data[(NBW_STR*NS_COLS)-i*NBW_STR-1-:NBW_STR];
    end
endgenerate

// ----------------------------------------
// - Output assignment
// ----------------------------------------
always_comb begin : output_assignment
    o_data = data[i_col_sel];
end

endmodule : column_selector

context/rtl/event_storage.sv:
module event_storage #(
    parameter NBW_STR = 'd4,
    parameter NS_EVT  = 'd4,
    parameter NBW_EVT = 'd2
) (
    input  logic       clk,
    input  logic       rst_async_n,
    input  logic       i_en_overflow,
    input  logic [3:0] i_event,
    input  logic [3:0] i_data,
    input  logic       i_bypass,
    input  logic [1:0] i_raddr,
    output logic [3:0] o_data
);

// ----------------------------------------
// - Wires/Registers creation
// ----------------------------------------
logic [3:0] reg_bank [0:3];

// ----------------------------------------
// - Block logic
// ----------------------------------------
generate
    for (genvar i = 0; i < 4; i++) begin : instantiate_regs
        always_ff @ (posedge clk or negedge rst_async_n) begin
            if(!rst_async_n) begin
                reg_bank[i] <= 0;
            end else begin
                if(i_en_overflow) begin
                    reg_bank[i] <= reg_bank[i] + i_event[i];
                end else begin
                    if(reg_bank[i] == 4'd15) begin
                        reg_bank[i] <= reg_bank[i];
                    end else begin
                        reg_bank[i] <= reg_bank[i] + i_event[i];
                    end
                end
            end
        end
    end
endgenerate

// ----------------------------------------
// - Output assignment
// ----------------------------------------
always_comb begin : output_assignment
    if(i_bypass) begin
        o_data = i_data;
    end else begin
        o_data = reg_bank[i_raddr];
    end
end

endmodule : event_storage

context/verif/tb.sv:
module tb;

localparam NS_ROWS = 'd4;
localparam NS_COLS = 'd4;
localparam NBW_COL = 'd2;
localparam NBW_STR = 'd8;
localparam NS_EVT  = 'd8;
localparam NBW_EVT = 'd3;

logic                                clk;
logic                                rst_async_n;
logic [NBW_COL-1:0]                  i_col_sel;
logic [NS_ROWS*NS_COLS-1:0]          i_en_overflow;
logic [(NS_ROWS*NS_COLS*NS_EVT)-1:0] i_event;
logic [(NS_ROWS*NBW_STR)-1:0]        i_data;
logic [NS_ROWS-1:0]                  i_bypass;
logic [NBW_EVT-1:0]                  i_raddr;
logic [NBW_STR-1:0]                  o_data;

event_array #(
    .NS_ROWS(NS_ROWS),
    .NS_COLS(NS_COLS),
    .NBW_COL(NBW_COL),
    .NBW_STR(NBW_STR),
    .NS_EVT(NS_EVT),
    .NBW_EVT(NBW_EVT)
) uu_event_array (
    .clk          (clk          ),
    .rst_async_n  (rst_async_n  ),
    .i_col_sel    (i_col_sel    ),
    .i_en_overflow(i_en_overflow),
    .i_event      (i_event      ),
    .i_data       (i_data       ),
    .i_bypass     (i_bypass     ),
    .i_raddr      (i_raddr      ),
    .o_data       (o_data       )
);

initial begin
    $dumpfile("test.vcd");
    $dumpvars(0,tb);
end

task SimpleTest(int line_to_read, int col_to_read, int r_addr);
    $display("---------------");
    $display("Running test reading row %2d, column %2d, address %2d", line_to_read, col_to_read, r_addr);
    @(negedge clk);
    i_en_overflow = 0;
    i_bypass = {NS_ROWS{1'b1}};
    i_bypass[line_to_read] = 1'b0;
    i_raddr = r_addr;
    i_col_sel = col_to_read;
    i_event = 0;

    for(int i = 1; i <= NS_ROWS*NS_COLS*NS_EVT; i++) begin
        for(int j = 0; j < i; j++) begin
            i_event[NS_ROWS*NS_COLS*NS_EVT-i] = 1'b1;
            @(negedge clk);
        end
        i_event = 0;
    end

    @(negedge clk);

    if((NS_EVT - r_addr + line_to_read*NS_COLS*NS_EVT + col_to_read*NS_EVT) > 2**NBW_STR - 1) begin
        if(o_data != 2**NBW_STR - 1) begin
            $display("FAIL! Received o_data = %2d, when it should have been %2d", o_data, 2**NBW_STR - 1);
        end else begin
            $display("PASS! Received o_data = %2d", o_data);
        end
    end else begin
        if(o_data != (NS_EVT - r_addr + line_to_read*NS_COLS*NS_EVT + col_to_read*NS_EVT)) begin
            $display("FAIL! Received o_data = %d, when it should have been %2d", o_data, (NS_EVT - r_addr + line_to_read*NS_COLS*NS_EVT + col_to_read*NS_EVT));
        end else begin
            $display("PASS! Received o_data = %d", o_data);
        end
    end
endtask

task Reset();
    i_col_sel     = 0;
    i_en_overflow = 0;
    i_event       = 0;
    i_data        = 0;
    i_bypass      = 0;
    i_raddr       = 0;
    rst_async_n = 1;
    #1;
    rst_async_n = 0;
    #2;
    rst_async_n = 1;
    @(negedge clk);
endtask

task TestOverflow(logic overflow);
    $display("---------------");
    $display("Testing overflow in row 0, column 0, address 0");
    @(negedge clk);
    i_en_overflow = overflow;
    i_bypass = {NS_ROWS{1'b1}};
    i_bypass[0] = 1'b0;
    i_raddr = 0;
    i_col_sel = 0;
    i_event = 0;

    for(int i = 0; i <= 2**NBW_STR; i++) begin
        i_event[NS_ROWS*NS_COLS*NS_EVT-NS_EVT] = 1'b1;
        @(negedge clk);
    end
    i_event = 0;

    @(negedge clk);

    if(overflow == 0) begin
        if(o_data != 2**NBW_STR - 1) begin
            $display("FAIL! Received o_data = %2d, when it should have been %2d", o_data, 2**NBW_STR - 1);
        end else begin
            $display("PASS! Received o_data = %2d", o_data);
        end
    end else begin
        if(o_data != 1) begin
            $display("FAIL! Received o_data = %2d, when it should have been %2d", o_data, 1);
        end else begin
            $display("PASS! Received o_data = %2d", o_data);
        end
    end
endtask

always #5 clk = ~clk;

int value;

initial begin
    clk = 0;
    value = 1;
    Reset();

    $display("----------------------");
    $display("This testbench writes:");
    for(int row = 0; row < NS_ROWS; row++) begin
        for(int col = 0; col < NS_COLS; col++) begin
            for(int addr = NS_EVT-1; addr >= 0; addr--) begin
                $display("%2d in row %2d, col %2d, address %2d", value, row, col, addr);
                value++;
            end
        end
    end

    $display("----------------------");
    $display("Note that, if any of those values are bigger than %2d, it will saturate when i_en_overflow = 0, and wrap around when i_en_overflow = 1.", 2**NBW_STR - 1);
    $display("----------------------");

    // Tasks go here
    SimpleTest(0, 0, 0);
    Reset();
    SimpleTest(1, 0, 0);
    Reset();
    SimpleTest(0, 1, 0);
    Reset();
    SimpleTest(0, 0, 1);
    Reset();
    SimpleTest(2, 1, 0);
    Reset();
    SimpleTest(1, 2, 2);
    Reset();
    SimpleTest(1, 2, 7);
    Reset();
    TestOverflow(1'b0);
    Reset();
    TestOverflow(1'b1);
    Reset();

    @(negedge clk);
    @(negedge clk);

    $finish();
end

endmodule

context/rtl/adder_2d_layers.sv:
module adder_2d_layers #(
    parameter NBW_IN   = 'd8        ,
    parameter NS_IN    = 'd80       ,
    parameter N_LEVELS = 'd7        ,
    parameter REGS     = 8'b100010_0,
    parameter NBW_ADDER_TREE_OUT = 8,
    parameter NBW_ENERGY = 5
) (
    input  logic                                clk    ,
    input  logic                               i_enable,
    input  logic [           NBW_IN*NS_IN-1:0] i_data_i,
    input  logic [           NBW_IN*NS_IN-1:0] i_data_q,
    output logic [(NBW_IN+N_LEVELS)-1:0] o_data_i,
    output logic [(NBW_IN+N_LEVELS)-1:0] o_data_q,
    output logic [NBW_IN-1:0] o_energy    
);

logic signed [NBW_ADDER_TREE_OUT-1:0] correlation_i_dff;
logic signed [NBW_ADDER_TREE_OUT-1:0] correlation_q_dff;

wire signed [2*NBW_ADDER_TREE_OUT-1:0] energy_i;
wire signed [2*NBW_ADDER_TREE_OUT-1:0] energy_q;
wire signed [2*NBW_ADDER_TREE_OUT:0] energy;

/*Sum all corelation_i components */
adder_tree_2d #(
    .NBW_IN  (NBW_IN  ),
    .NS_IN   (NS_IN   ),
    .N_LEVELS(N_LEVELS),
    .REGS    (REGS    ) 
) uu_sum_corr_i (
        .clk   (clk            ),
        .i_data(i_data_i       ),
        .o_data(o_data_i       )
);

/*Sum all corelation_q components */
adder_tree_2d #(
    .NBW_IN  (NBW_IN  ),
    .NS_IN   (NS_IN   ),
    .N_LEVELS(N_LEVELS),
    .REGS    (REGS    ) 
) uu_sum_corr_q (
        .clk   (clk            ),
        .i_data(i_data_q       ),
        .o_data(o_data_q       )
);

always_ff @(posedge clk) begin : proc_correlation_dff
  if(i_enable) begin
      correlation_i_dff <= o_data_i;
      correlation_q_dff <= o_data_q;
   end 
end

assign energy_i  = correlation_i_dff*correlation_i_dff;
assign energy_q  = correlation_q_dff*correlation_q_dff;
assign energy    = $unsigned(energy_i) + $unsigned(energy_q);
assign o_energy  = energy[2*NBW_ADDER_TREE_OUT-:NBW_ENERGY];


endmodule

context/rtl/correlate.sv:
module correlate #(
   parameter  NS_DATA_IN        = 'd11,
   parameter  NBW_DATA_IN = 'd08,
   parameter  NBW_ADDER_TREE_IN = 3
)
(
 input  logic [NBW_DATA_IN*NS_DATA_IN-1 : 0]  i_data_i    ,
 input  logic [NBW_DATA_IN*NS_DATA_IN-1 : 0]  i_data_q    ,
 input  logic        [       NS_DATA_IN-1 : 0]  i_conj_seq_i,
 input  logic        [       NS_DATA_IN-1 : 0]  i_conj_seq_q,   
 output logic [NBW_ADDER_TREE_IN*NS_DATA_IN-1:0]o_sum_i,
 output logic [NBW_ADDER_TREE_IN*NS_DATA_IN-1:0]o_sum_q

);

wire signed  [      NBW_DATA_IN:0] add[NS_DATA_IN];
wire signed  [      NBW_DATA_IN:0] sub[NS_DATA_IN];

logic signed [NBW_ADDER_TREE_IN-1:0] sum_i[NS_DATA_IN];
logic signed [NBW_ADDER_TREE_IN-1:0] sum_q[NS_DATA_IN];

logic signed [NBW_DATA_IN-1:0]  i_data_i_2d [NS_DATA_IN-1:0]; 
logic signed [NBW_DATA_IN-1:0]  i_data_q_2d [NS_DATA_IN-1:0]; 

wire [NS_DATA_IN-1:0] signal_seq_i;
wire [NS_DATA_IN-1:0] signal_seq_q;

always_comb begin
    for (int i=0; i<NS_DATA_IN; i++) begin
        i_data_i_2d[i] = $signed(i_data_i[(i+1)*NBW_DATA_IN-1-:NBW_DATA_IN]);
        i_data_q_2d[i] = $signed(i_data_q[(i+1)*NBW_DATA_IN-1-:NBW_DATA_IN]);
    end
end

generate
    for(genvar i = 0 ; i < NS_DATA_IN; i++) begin
        
        /*determinate the signal of the FAW symbs*/
        assign signal_seq_i[i] = i_conj_seq_i[i];
        assign signal_seq_q[i] = i_conj_seq_q[i];


        assign add[i] = i_data_i_2d[i] + i_data_q_2d[i];
        assign sub[i] = i_data_i_2d[i] - i_data_q_2d[i];
    
        always_comb begin
            case({signal_seq_i[i],signal_seq_q[i]})
                2'b00: begin
                            sum_i[i]  = sub[i];
                            sum_q[i]  = add[i];
                       end

                2'b01: begin
                            sum_i[i]  =  add[i];
                            sum_q[i]  = -sub[i];
                       end    

                2'b10: begin
                            sum_i[i]  = -add[i];
                            sum_q[i]  =  sub[i];
                       end    

                2'b11: begin
                            sum_i[i]  = -sub[i];
                            sum_q[i]  = -add[i];
                       end    
            endcase 
        end
    end    
endgenerate

always_comb begin
    for (int i=0; i<NS_DATA_IN; ++i) begin
        o_sum_i[(i+1)*NBW_ADDER_TREE_IN-1-:NBW_ADDER_TREE_IN] = sum_i[i];
        o_sum_q[(i+1)*NBW_ADDER_TREE_IN-1-:NBW_ADDER_TREE_IN] = sum_q[i];
    end
end
endmodule

context/rtl/cross_correlation.sv:
module cross_correlation #(
   parameter  NS_DATA_IN  = 'd11,
   parameter  NBW_DATA_IN = 'd08,
   parameter  NBI_DATA_IN = 'd02,   
   parameter  NBW_ENERGY  = 'd08
)
( 
 input  logic                                clk         ,
 input  logic                                i_enable    , 
 input  logic [NBW_DATA_IN*NS_DATA_IN-1 : 0] i_data_i    ,
 input  logic [NBW_DATA_IN*NS_DATA_IN-1 : 0] i_data_q    ,
 input  logic [NS_DATA_IN-1:0]               i_conj_seq_i,
 input  logic [NS_DATA_IN-1:0]               i_conj_seq_q,
 output logic [NBW_ENERGY-1:0]               o_energy  
);
localparam N_ADDER_LEVELS= $clog2(NS_DATA_IN);
localparam N_REG_LEVELS  = 8'b00000000;

localparam NBW_ADDER_TREE_IN  = NBW_DATA_IN + 2;
localparam NBI_ADDER_TREE_IN  = NBI_DATA_IN + 2;

localparam NBW_ADDER_TREE_OUT = NBW_ADDER_TREE_IN  + N_ADDER_LEVELS;
localparam NBI_ADDER_TREE_OUT = NBI_ADDER_TREE_IN  + N_ADDER_LEVELS;
localparam NBF_ADDER_TREE_OUT = NBW_ADDER_TREE_OUT - NBI_ADDER_TREE_OUT;

logic [NBW_ADDER_TREE_IN*NS_DATA_IN-1:0] sum_i_1d;
logic [NBW_ADDER_TREE_IN*NS_DATA_IN-1:0] sum_q_1d;

/*Correlation result for i and q data component*/
wire signed [NBW_ADDER_TREE_OUT-1:0] correlation_i;
wire signed [NBW_ADDER_TREE_OUT-1:0] correlation_q;

correlate #(
    .NS_DATA_IN       (NS_DATA_IN       ),
    .NBW_DATA_IN      (NBW_DATA_IN      ),
    .NBW_ADDER_TREE_IN(NBW_ADDER_TREE_IN)
) uu_correlate(
    .i_data_i    (i_data_i    ),
    .i_data_q    (i_data_q    ),
    .i_conj_seq_i(i_conj_seq_i),
    .i_conj_seq_q(i_conj_seq_q),   
    .o_sum_i     (sum_i_1d    ),
    .o_sum_q     (sum_q_1d    )
);

adder_2d_layers  #(
    .NBW_IN            (NBW_ADDER_TREE_IN ),
    .NS_IN             (NS_DATA_IN        ),
    .N_LEVELS          (N_ADDER_LEVELS    ),
    .REGS              (N_REG_LEVELS      ),
    .NBW_ADDER_TREE_OUT(NBW_ADDER_TREE_OUT),
    .NBW_ENERGY        (NBW_ENERGY        )
) uu_adder_2d_layers (
        .clk     (clk            ),
        .i_enable(i_enable       ),
        .i_data_i(sum_i_1d       ),
        .i_data_q(sum_q_1d       ),
        .o_data_i(correlation_i  ),
        .o_data_q(correlation_q  ),
        .o_energy(o_energy)            
);

endmodule

context/rtl/detect_sequence.sv:
module detect_sequence #(
    parameter    NS              =  'd64      ,
    parameter    NBW_PILOT_POS   =  'd06      ,
    parameter    NBW_DATA_IN     =  'd08      ,
    parameter    NBI_DATA_IN     =  'd02      ,
    parameter    NBW_TH_PROC     =  'd10      ,
    parameter    NBW_ENERGY      =  'd10      ,
    parameter    NS_PROC         =  'd23      ,
    parameter    NS_PROC_OVERLAP =  NS_PROC - 1
)
(
    input  logic                                        clk               ,
    input  logic                                        rst_async_n       ,
    input  logic                                        i_valid           ,
    input  logic                                        i_enable          ,
    input  logic                                        i_proc_pol        ,
    input  logic [NBW_PILOT_POS-1:0]                    i_proc_pos        ,
    input  logic [NBW_TH_PROC-1:0]                      i_static_threshold,
    input  logic [NBW_DATA_IN*(NS+NS_PROC_OVERLAP)-1:0] i_data_i          ,
    input  logic [NBW_DATA_IN*(NS+NS_PROC_OVERLAP)-1:0] i_data_q          ,
    output logic                                        o_proc_detected    
);
localparam   PROC_CORR_ADDER_LEVELS   = $clog2(NS_PROC);
localparam   PROC_CORR_REG_LEVELS     = 8'b00000000;
localparam   PIPE_DEPTH              = 3;

logic [NS_PROC-1:0] conj_proc_h[2];
logic [NS_PROC-1:0] conj_proc_v[2];

assign conj_proc_h[1] = 23'b11011001100011010001110;
assign conj_proc_v[1] = 23'b10000101011110000101011;

assign conj_proc_h[0] = 23'b10101010111011101000000;
assign conj_proc_v[0] = 23'b11010110101100100001110;

logic signed [NBW_DATA_IN-1:0]  i_data_i_2d[(NS+NS_PROC_OVERLAP)];
logic signed [NBW_DATA_IN-1:0]  i_data_q_2d[(NS+NS_PROC_OVERLAP)];

always_comb begin
    for (int i=0; i<(NS+NS_PROC_OVERLAP); i++) begin
        i_data_i_2d[i] = $signed(i_data_i[(i+1)*NBW_DATA_IN-1-:NBW_DATA_IN]);
        i_data_q_2d[i] = $signed(i_data_q[(i+1)*NBW_DATA_IN-1-:NBW_DATA_IN]);
    end
end

logic  [PIPE_DEPTH-1:0] proc_enable_dff;

logic  proc_detected_dff;

logic  proc_pol_dff;

logic signed [NBW_DATA_IN-1:0] proc_buffer_i_dff[NS_PROC];
logic signed [NBW_DATA_IN-1:0] proc_buffer_q_dff[NS_PROC];
logic signed [NBW_DATA_IN*NS_PROC-1:0] proc_buffer_i_dff_1d;
logic signed [NBW_DATA_IN*NS_PROC-1:0] proc_buffer_q_dff_1d;
logic                     proc_enable;      
logic [NBW_ENERGY  -1 :0] proc_calc_energy; 
logic [       NS_PROC-1:0] conj_proc_seq[2];

assign proc_enable  = i_valid & i_enable;

always_ff @(posedge clk or negedge rst_async_n) begin : proc_proc_enable_dff
  if(~rst_async_n) 
    proc_enable_dff <= {PIPE_DEPTH{1'b0}};
  else begin
    proc_enable_dff[0] <= proc_enable;
    for(int i = 1 ; i < PIPE_DEPTH ; i++)
      proc_enable_dff[i] <= proc_enable_dff[i-1];
  end
end

always_ff @(posedge clk) begin
    if(proc_enable) begin
      for(int i = 0; i < NS_PROC; i++) begin
        proc_buffer_i_dff[i] <=  i_data_i_2d[i_proc_pos + i];
        proc_buffer_q_dff[i] <=  i_data_q_2d[i_proc_pos + i];
      end
    end
end

always_ff @(posedge clk or negedge rst_async_n) begin
    if(~rst_async_n)
        proc_pol_dff <= 1'b0;
    else      
      if(proc_enable)
        proc_pol_dff <=  i_proc_pol;
end

always_comb begin
  if(proc_pol_dff) begin
    conj_proc_seq[0] = conj_proc_v[0];
    conj_proc_seq[1] = conj_proc_v[1];
  end
  else begin
    conj_proc_seq[0] = conj_proc_h[0];
    conj_proc_seq[1] = conj_proc_h[1];    
  end
end

always_comb begin
  for (int i=0; i<NS_PROC; ++i) begin
    proc_buffer_i_dff_1d[(i+1)*NBW_DATA_IN-1-:NBW_DATA_IN] = proc_buffer_i_dff[i];
    proc_buffer_q_dff_1d[(i+1)*NBW_DATA_IN-1-:NBW_DATA_IN] = proc_buffer_q_dff[i];
  end
end

cross_correlation #(
        .NS_DATA_IN  (NS_PROC     ),
        .NBW_DATA_IN (NBW_DATA_IN ),
        .NBI_DATA_IN (NBI_DATA_IN ),
        .NBW_ENERGY  (NBW_ENERGY  )
  ) uu_cross_correlation(
     .clk         (clk                 ),
     .i_enable    (proc_enable_dff[0]  ),
     .i_data_i    (proc_buffer_i_dff_1d),
     .i_data_q    (proc_buffer_q_dff_1d),
     .i_conj_seq_i(conj_proc_seq[0]    ),
     .i_conj_seq_q(conj_proc_seq[1]    ),
     .o_energy    (proc_calc_energy    )
);

assign proc_detected  =   (proc_calc_energy >= i_static_threshold ) && proc_enable_dff[2]; 

always_ff @(posedge clk or negedge rst_async_n) begin : proc_proc_detected_dff
  if(~rst_async_n) 
     proc_detected_dff <= 1'b0;
  else
     proc_detected_dff <=  proc_detected;
end

assign o_proc_detected = proc_detected_dff;

endmodule

context/rtl/prbs_gen_check.sv:
/**************************************************************************
FILENAME:    prbs_gen_check.sv
DESCRIPTION: This module generates or checks a PRBS pattern.
**************************************************************************/

module prbs_gen_check #(
   parameter CHECK_MODE  = 0,              // 0: uses LFSR structure to generate a PRBS pattern, 1: the incoming data is loaded into prbs registers and compared with locally generated PRBS pattern.
   parameter POLY_LENGTH = 31,             // length of the polynomial.(number of shift register stages)
   parameter POLY_TAP    = 3,              // Intermedite stage that is xored with the last stage to generate the next prbs bit.
   parameter WIDTH       = 16              // Bus size of data_in and data_out.
   )(
   input                         clk     , // clock input
   input                         rst     , // synchronous reset, active high
   input         [WIDTH-1:0]     data_in , // input data to be checked(checker mode), tied to 0 (generator mode)
   output logic  [WIDTH-1:0]     data_out  // generated prbs pattern (generator mode), error found (checker mode).
);

logic [1:POLY_LENGTH] prbs [WIDTH:0];
logic [WIDTH-1:0]     prbs_xor_a;
logic [WIDTH-1:0]     prbs_xor_b;
logic [WIDTH:1]       prbs_msb;
logic [1:POLY_LENGTH] prbs_reg = {(POLY_LENGTH){1'b1}};

assign prbs[0]   = prbs_reg;

genvar i;
generate for(i=0; i<WIDTH; i=i+1) begin
   assign prbs_xor_a[i] = prbs[i][POLY_TAP] ^ prbs[i][POLY_LENGTH];
   assign prbs_xor_b[i] = prbs_xor_a[i] ^ data_in[i];
   assign prbs_msb[i+1] = (CHECK_MODE==0) ? prbs_xor_a[i] : data_in[i];
   assign prbs[i+1]     = {prbs_msb[i+1],prbs[i][1:POLY_LENGTH-1]};
end
endgenerate

always_ff @ (posedge clk) begin
   if(rst) begin
      prbs_reg <= {POLY_LENGTH{1'b1}};
      data_out <= {WIDTH{1'b1}};
   end else begin
      prbs_reg <= prbs[WIDTH];
      data_out <= prbs_xor_b;   
   end
end
  
endmodule

context/rtl/APBGlobalHistoryRegister.v:
module APBGlobalHistoryRegister (
    // APB clock & reset
    input  wire         pclk,  //APB clock input used for all synchronous operations.
    input  wire         presetn,  // Asynchronous reset for system initialization.

    // APB signals
    input  wire [9:0]   paddr,  //Address bus for accessing internal CSR registers.
    input  wire         pselx,  //APB select signal, indicates CSR/memory selection.
    input  wire         penable,  //APB enable signal, marks transaction progression.
    input  wire         pwrite, //Write-enable signal. High for writes, low for reads.
    input  wire [7:0]   pwdata, // Write data bus for sending data to CSR registers or memory.
    input  wire         history_shift_valid,  
    input  wire         clk_gate_en,  
    output reg          pready, // Ready signal, driven high to indicate the end of a transaction.
    output reg  [7:0]   prdata, // Read data bus for retrieving data from the module.
    output reg          pslverr,  //Error signal, asserted on invalid addresses.
    output reg          history_full, 
    output reg          history_empty,  
    output reg          error_flag, 
    output reg          interrupt_full, 
    output reg          interrupt_error 
);

    //---------------------------------------------
    // Parameter Definitions
    //---------------------------------------------
    // Register address map
    localparam ADDR_CTRL_REG     = 10'h0;  // 0x0
    localparam ADDR_TRAIN_HIS    = 10'h1;  // 0x1
    localparam ADDR_PREDICT_HIS  = 10'h2;  // 0x2

    localparam WIDTH             = 8;

    //---------------------------------------------
    // Internal Registers (CSR)
    //---------------------------------------------
    reg [WIDTH-1:0] control_register;
    reg [WIDTH-1:0] train_history;
    reg [WIDTH-1:0] predict_history;
    //---------------------------------------------
    // Internal wires
    //---------------------------------------------
    wire        predict_valid;
    wire        predict_taken;
    wire        train_mispredicted;
    wire        train_taken;
    //---------------------------------------------
    // APB Read/Write Logic
    //---------------------------------------------
    wire apb_valid;
    assign apb_valid = pselx & penable;    // Indicates active APB transaction
    assign pclk_gated = !clk_gate_en&pclk;
    // By spec, no wait states => PREADY always high after reset
    always @(posedge pclk_gated or negedge presetn) begin
      if (!presetn) begin
        pready   <= 1'b0;
        pslverr  <= 1'b0;
      end else begin
        // PREADY is always asserted (no wait states) once out of reset
        pready   <= 1'b1;
        // If transaction is valid, check address range
        if (apb_valid) begin
          // Check if address is valid (0x0 through 0x2 are used, everything else => PSLVERR)
          if (paddr > ADDR_PREDICT_HIS) begin
            pslverr <= 1'b1;
          end
          else begin
            pslverr  <= 1'b0;
          end
        end
      end
    end

    // Handle writes to CSR or memory
    // Note: The design writes immediately in the cycle when penable=1.
    always @(posedge pclk_gated or negedge presetn) begin
      if (!presetn) begin
        // Reset all registers
        control_register  <= 0;
        train_history     <= 0;
      end else begin
        if (apb_valid && pwrite) begin
          case (paddr)
              ADDR_CTRL_REG:    control_register[3:0]  <= pwdata[3:0];
              ADDR_TRAIN_HIS:   train_history[6:0]     <= pwdata[6:0];
              // If the address is outside defined range => PSLVERR is set, no write
          endcase
        end
      end
    end

    // Handle read from CSR or memory
    always @(posedge pclk_gated or negedge presetn) begin
      if (!presetn) begin
        prdata <= 0;
      end 
      else begin
        if (apb_valid) begin
          case (paddr)
            ADDR_CTRL_REG:    prdata <= {4'b0,control_register[3:0]};
            ADDR_TRAIN_HIS:   prdata <= {1'b0,train_history[6:0]};
            ADDR_PREDICT_HIS: prdata <= predict_history;
            default:          prdata <= 0; // Invalid => PSLVERR, but can set prdata to 0
          endcase
        end
        else begin
          // When no valid read, clear prdata
          prdata <= 0;
        end
      end
    end


    //---------------------------------------------
    // GHSR Behavior
    //---------------------------------------------

    assign  predict_valid       = control_register[0];     // valid branch prediction
    assign  predict_taken       = control_register[1];     // predicted direction (1=taken, 0=not taken)
    assign  train_mispredicted  = control_register[2];     // branch misprediction occurred
    assign  train_taken         = control_register[3];     // actual branch direction for mispredicted branch



    always @(posedge history_shift_valid or negedge presetn) begin
      if (!presetn) begin
        // 1) active low Asynchronous reset
        //    Clear the entire history register.
        predict_history <= 0;
      end
      else begin
        // 2) Misprediction Handling (highest priority)
        //    If a misprediction is flagged, restore the old history from train_history
        //    and incorporate the correct outcome (train_taken) as the newest bit.
        if (train_mispredicted) begin
          predict_history <= {train_history[WIDTH-2:0], train_taken};
        end
        // 3) Normal Prediction Update
        //    If the prediction is valid and there is no misprediction,
        //    shift in predict_taken at the LSB (bit[0] is the youngest branch).
        else if (predict_valid) begin
          // "Shifting in from the LSB" while keeping the newest branch in predict_history[0]
          // is typically done by moving predict_history[31:1] up one bit
          // and placing predict_taken in bit[0].
          predict_history <= {predict_history[WIDTH-2:0], predict_taken};
        end
      end
    end
    
    always @(*) begin
      error_flag=pslverr;
      interrupt_error=pslverr;
      if(predict_history==8'hff) begin
        history_full=1'b1;
        interrupt_full=1'b1;
        history_empty=1'b0;
      end
      else if (predict_history==8'h00) begin
        history_full=1'b0;
        interrupt_full=1'b0;
        history_empty=1'b1;
      end
      else begin
        history_full=1'b0;
        interrupt_full=1'b0;
        history_empty=1'b0;
      end
    end

endmodule

context/rtl/brick_sort.sv:
module brick_sorting_engine #(
    parameter N = 8,             // Number of elements to sort
    parameter WIDTH = 8          // Bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    // ----------------------------------------------------------
    // Internal Parameters and State Encoding
    // ----------------------------------------------------------
    localparam IDLE = 2'd0,
               LOAD = 2'd1,
               SORT = 2'd2,
               DONE = 2'd3;

    // ----------------------------------------------------------
    // Internal Registers
    // ----------------------------------------------------------
    reg [1:0]  state, next_state;

    // Store data in a register array for easy swapping
    reg [WIDTH-1:0] data_array [0:N-1];

    // Pass counter: we will run up to N passes
    reg [$clog2(N+1)-1:0] pass_cnt;

    // Pair index: on each pass, we compare-swap one pair per clock
    reg [$clog2(N/2+1):0] pair_idx;

    // ----------------------------------------------------------
    // Next-State Logic
    // ----------------------------------------------------------
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start)
                    next_state = LOAD;
            end

            LOAD: begin
                // After loading input data, go to SORT state
                next_state = SORT;
            end

            SORT: begin
                // Once we've completed N passes, sorting is done
                if (pass_cnt == N)
                    next_state = DONE;
            end

            DONE: begin
                // Optionally return to IDLE if desired
                // For a one-shot, we can just stay in DONE unless reset
                // Here, we return to IDLE if start is deasserted
                if (!start)
                    next_state = IDLE;
            end
        endcase
    end

    // ----------------------------------------------------------
    // Sequential State Update
    // ----------------------------------------------------------
    always @(posedge clk or posedge rst) begin
        if (rst)
            state <= IDLE;
        else
            state <= next_state;
    end

    // ----------------------------------------------------------
    // Main Control: pass_cnt, pair_idx, and compare-swap
    // ----------------------------------------------------------
    integer i;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            done      <= 1'b0;
            pass_cnt  <= 0;
            pair_idx  <= 0;
        end
        else begin
            case (state)

                //--------------------------------------
                // IDLE: wait for start, clear signals
                //--------------------------------------
                IDLE: begin
                    done     <= 1'b0;
                    pass_cnt <= 0;
                    pair_idx <= 0;
                end

                //--------------------------------------
                // LOAD: capture input data into array
                //--------------------------------------
                LOAD: begin
                    // Load all N elements from in_data
                    for (i = 0; i < N; i = i + 1) begin
                        data_array[i] <= in_data[i*WIDTH +: WIDTH];
                    end
                    // Initialize counters
                    pass_cnt <= 0;
                    pair_idx <= 0;
                end

                //--------------------------------------
                // SORT: perform Brick Sort passes
                //--------------------------------------
                SORT: begin
                    // Compare-swap the current pair
                    // Check if we are within the valid pair range
                    // Distinguish odd-even pass from even-odd pass
                    if (pass_cnt[0] == 1'b0) begin
                        // even-odd pass => pair = (2*pair_idx, 2*pair_idx+1)
                        for(pair_idx=0; pair_idx<(N+1)/2; pair_idx=pair_idx+1) begin
                            if (data_array[2*pair_idx] > data_array[2*pair_idx+1]) begin
                                // Swap
                                {data_array[2*pair_idx], data_array[2*pair_idx+1]} <= {data_array[2*pair_idx+1], data_array[2*pair_idx]};
                            end
                        end
                    end
                    else begin
                        // odd-even pass => pair = (2*pair_idx+1, 2*pair_idx+2
                        for(pair_idx=0; pair_idx<((N+1)/2) - 1; pair_idx=pair_idx+1) begin
                            if ((2*pair_idx+2) < N) begin
                                if (data_array[2*pair_idx+1] > data_array[2*pair_idx+2]) begin
                                    // Swap
                                    {data_array[2*pair_idx+1], data_array[2*pair_idx+2]} <= {data_array[2*pair_idx+2], data_array[2*pair_idx+1]};
                                end
                            end
                        end
                    end

                    // Completed all pairs in this pass -> next pass
                    pass_cnt <= pass_cnt + 1;

                end // SORT

                //--------------------------------------
                // DONE: output final data, assert done
                //--------------------------------------
                DONE: begin
                    done <= 1'b1;
                    // Drive out_data from data_array
                    for (i = 0; i < N; i = i + 1) begin
                        out_data[i*WIDTH +: WIDTH] <= data_array[i];
                    end
                end

            endcase
        end
    end

endmodule

context/rtl/bubble_sort.sv:
module bubble_sorting_engine #(
    parameter N = 8,             // Number of elements to sort
    parameter WIDTH = 8          // Bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    // Internal registers to hold the array
    reg [WIDTH-1:0] array [0:N-1];

    // FSM states
    localparam IDLE    = 2'd0;
    localparam SORTING = 2'd1;
    localparam DONE    = 2'd2;

    reg [1:0]  state, next_state;

    // Variables for bubble sort indexing
    reg [$clog2(N)-1:0] i;  // Outer loop index
    reg [$clog2(N)-1:0] j;  // Inner loop index

    // Wires for comparison and swap
    wire [WIDTH-1:0] val_j;
    wire [WIDTH-1:0] val_j1;

    assign val_j  = array[j];
    assign val_j1 = array[j+1];

    // FSM: Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start)
                    next_state = SORTING;
            end
            SORTING: begin
                // Transition to DONE once all passes are complete
                if (i == (N-1) && j == (N-2))
                    next_state = DONE;
            end
            DONE: begin
                next_state = IDLE;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // FSM: Output and counter updates
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            i <= 0;
            j <= 0;
            done <= 0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Load the array from in_data
                        for (int k = 0; k < N; k = k + 1) begin
                            array[k] <= in_data[(k+1)*WIDTH-1 -: WIDTH];
                        end
                        i <= 0;
                        j <= 0;
                    end
                end

                SORTING: begin
                    // Perform a single comparison and swap if needed
                    if (val_j > val_j1) begin
                        array[j]   <= val_j1;
                        array[j+1] <= val_j;
                    end

                    // Update j
                    if (j == N-2) begin
                        // One pass completed, increment i
                        j <= 0;
                        i <= i + 1;
                    end else begin
                        j <= j + 1;
                    end
                end

                DONE: begin
                    // Sorting complete
                    done <= 1;
                    // Output the sorted data
                    for (int m = 0; m < N; m = m + 1) begin
                        out_data[(m+1)*WIDTH-1 -: WIDTH] <= array[m];
                    end
                end
                default: begin
                end
            endcase
        end
    end

endmodule

context/rtl/merge_sort.sv:
module merge_sorting_engine #(
    parameter N = 8,             // Number of elements to sort
    parameter WIDTH = 8          // Bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    //-------------------------------------------------
    // Local Parameters & Functions
    //-------------------------------------------------
    localparam IDLE  = 0;
    localparam LOAD  = 1;
    localparam SORT  = 2;
    localparam MERGE = 3;
    localparam DONE  = 4;

    // Function to compute floor(log2(value)) at compile time
    function integer clog2;
        input integer value;
        integer i;
        begin
            clog2 = 0;
            for (i = 1; i < value; i = i << 1) begin
                clog2 = clog2 + 1;
            end
        end
    endfunction

    // We choose ADDR_WIDTH big enough so we can store up to ~4*N in subarray_size
    // For N=8, 4*N=32 => log2(32)=5 => plus 1 => 6 bits => can store up to 63 safely.
    localparam ADDR_WIDTH = clog2(4 * N) + 1;

    //-------------------------------------------------
    // Internal Signals
    //-------------------------------------------------
    reg [2:0]                 state; // Enough for 5 states: IDLE..DONE

    // Internal memory of N elements
    reg [WIDTH-1:0]           data_mem [0:N-1];

    // Indices and counters with widened bit-width
    reg [ADDR_WIDTH-1:0]      base_idx;
    reg [ADDR_WIDTH-1:0]      left_idx;
    reg [ADDR_WIDTH-1:0]      right_idx;
    reg [ADDR_WIDTH-1:0]      merge_idx;
    reg [ADDR_WIDTH-1:0]      subarray_size;

    // Temporary buffer for merged sub-array
    reg [WIDTH-1:0]           tmp_merge [0:N-1];

    // Temporary registers for current left/right values
    reg [WIDTH-1:0]           left_val;
    reg [WIDTH-1:0]           right_val;

    integer i, k;
    integer left_end, right_end;
    integer l_addr,    r_addr;

    //-------------------------------------------------
    // State Machine
    //-------------------------------------------------
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset
            state         <= IDLE;
            done          <= 1'b0;
            out_data      <= {N*WIDTH{1'b0}};
            base_idx      <= 0;
            left_idx      <= 0;
            right_idx     <= 0;
            merge_idx     <= 0;
            subarray_size <= 1;
        end else begin
            case (state)

                //----------------------------------
                // IDLE: Wait for start signal
                //----------------------------------
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= LOAD;
                    end
                end

                //----------------------------------
                // LOAD: Copy from in_data to data_mem
                //----------------------------------
                LOAD: begin
                    for (i = 0; i < N; i = i + 1) begin
                        data_mem[i] <= in_data[i*WIDTH +: WIDTH];
                    end

                    // Initialize for sorting
                    base_idx      <= 0;
                    left_idx      <= 0;
                    right_idx     <= 0;
                    merge_idx     <= 0;
                    subarray_size <= 1;

                    state <= SORT;
                end

                //----------------------------------
                // SORT: Each pass merges sub-arrays of size subarray_size
                //----------------------------------
                SORT: begin
                    // If subarray_size is strictly greater than N, we've fully sorted
                    // (ensures we do a merge pass at subarray_size == N)
                    if (subarray_size >= N) begin
                        state <= DONE;
                    end else begin
                        // Prepare to merge pairs of sub-arrays
                        base_idx  <= 0;
                        merge_idx <= 0;
                        left_idx  <= 0;
                        right_idx <= 0;
                        state     <= MERGE;
                    end
                end

                //----------------------------------
                // MERGE: Merge one pair of sub-arrays
                //----------------------------------
                MERGE: begin
                    // Compare/pick smaller
                    if ((l_addr <= left_end) && (r_addr <= right_end)) begin
                        if (left_val <= right_val) begin
                            tmp_merge[merge_idx] <= left_val;
                            left_idx <= left_idx + 1;
                        end else begin
                            tmp_merge[merge_idx] <= right_val;
                            right_idx <= right_idx + 1;
                        end
                        merge_idx <= merge_idx + 1;
                    end
                    else if (l_addr <= left_end) begin
                        // Only left sub-array has data
                        tmp_merge[merge_idx] <= left_val;
                        left_idx <= left_idx + 1;
                        merge_idx <= merge_idx + 1;
                    end
                    else if (r_addr <= right_end) begin
                        // Only right sub-array has data
                        tmp_merge[merge_idx] <= right_val;
                        right_idx <= right_idx + 1;
                        merge_idx <= merge_idx + 1;
                    end
                    else begin
                        // Both sub-arrays are exhausted => write back merged results
                        for (k = 0; k < N; k = k + 1) begin
                            if ( (k < merge_idx) && (k < (subarray_size << 1)) && ((base_idx + k) < N) )
                            begin
                                data_mem[base_idx + k] <= tmp_merge[k];
                            end
                        end

                        // Move base_idx to next pair of sub-arrays
                        base_idx  <= base_idx + (subarray_size << 1);
                        left_idx  <= 0;
                        right_idx <= 0;
                        merge_idx <= 0;

                        // If we merged all pairs in this pass, double subarray_size
                        if ((base_idx + (subarray_size << 1)) >= N) begin
                            subarray_size <= subarray_size << 1;
                            state         <= SORT;
                        end
                    end
                end

                //----------------------------------
                // DONE: Output the fully sorted array
                //----------------------------------
                DONE: begin
                    for (i = 0; i < N; i = i + 1) begin
                        out_data[i*WIDTH +: WIDTH] <= data_mem[i];
                    end
                    done  <= 1'b1;
                    state <= IDLE;  // or remain in DONE, your preference
                end

                default: state <= IDLE;
            endcase
        end
    end

always @ (*) begin
    if(state == MERGE) begin
        left_end  = base_idx + subarray_size - 1;
        right_end = base_idx + (subarray_size << 1) - 1;

        // Boundaries of left and right sub-arrays
        if (left_end >= N) left_end = N - 1;
        if (right_end >= N) right_end = N - 1;

        // Calculate addresses
        l_addr = base_idx + left_idx;
        r_addr = base_idx + subarray_size + right_idx;

        // Safe read for left_val
        if ((l_addr <= left_end) && (l_addr < N))
            left_val = data_mem[l_addr];
        else
            left_val = {WIDTH{1'b1}};  // or '0' if you prefer

        // Safe read for right_val
        if ((r_addr <= right_end) && (r_addr < N))
            right_val = data_mem[r_addr];
        else
            right_val = {WIDTH{1'b1}};
    end else begin
        left_end = 0;
        right_end = 0;
        l_addr = 0;
        r_addr = 0;
        left_val = 0;
        right_val = 0;
    end
end

endmodule

context/rtl/selection_sort.sv:
module selection_sorting_engine #(
    parameter N = 8,
    parameter WIDTH = 8
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    typedef enum logic [2:0] {
        IDLE  = 3'd0,
        LOAD  = 3'd1,
        FIND  = 3'd2,
        CHECK = 3'd3,
        SWAP  = 3'd4,
        NEXT  = 3'd5,
        DONE  = 3'd6
    } state_t;

    state_t current_state, next_state;

    reg [WIDTH-1:0] data_array [0:N-1];

    reg [$clog2(N)-1:0] i;
    reg [$clog2(N)-1:0] j;
    reg [$clog2(N)-1:0] min_idx;

    reg [WIDTH-1:0] min_val;
    integer idx;
    integer k;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            current_state <= IDLE;
        end
        else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        next_state = current_state;
        case (current_state)
            IDLE: begin
                if (start)
                    next_state = LOAD;
            end

            LOAD: begin
                next_state = FIND;
            end

            FIND: begin
                next_state = CHECK;
            end

            CHECK: begin
                if (j == N-1)
                    next_state = SWAP;
                else
                    next_state = CHECK;
            end

            SWAP: begin
                next_state = NEXT;
            end

            NEXT: begin
                if (i == N-2)
                    next_state = DONE;
                else
                    next_state = FIND;
            end

            DONE: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            done     <= 1'b0;
            out_data <= {N*WIDTH{1'b0}};
        end
        else begin
            done <= (current_state == DONE);

            if (current_state == DONE) begin
                for (idx = 0; idx < N; idx = idx + 1) begin
                    out_data[idx*WIDTH +: WIDTH] <= data_array[idx];
                end
            end
        end
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (k = 0; k < N; k = k + 1) begin
                data_array[k] <= {WIDTH{1'b0}};
            end
            i       <= 0;
            j       <= 0;
            min_idx <= 0;
            min_val <= {WIDTH{1'b0}};
        end
        else begin
            case (current_state)

                IDLE: begin
                end

                LOAD: begin
                    for (k = 0; k < N; k = k + 1) begin
                        data_array[k] <= in_data[k*WIDTH +: WIDTH];
                    end
                    i       <= 0;
                    j       <= 0;
                    min_idx <= 0;
                    min_val <= {WIDTH{1'b0}};
                end

                FIND: begin
                    j          <= i + 1;
                    min_idx    <= i;
                    min_val    <= data_array[i];
                end

                CHECK: begin
                    if (data_array[j] < min_val) begin
                        min_val    <= data_array[j];
                        min_idx    <= j;
                    end

                    if (j < N-1) begin
                        j <= j + 1;
                    end
                end

                SWAP: begin
                    if (min_idx != i) begin
                        data_array[i]        <= data_array[min_idx];
                        data_array[min_idx]  <= data_array[i];
                    end
                end

                NEXT: begin
                    i <= i + 1;
                end

                DONE: begin
                end

                default: begin
                end
            endcase
        end
    end

endmodule

context/rtl/swizzler.sv:
`timescale 1ns/1ps

module swizzler #(
  parameter integer NUM_LANES           = 4,
  parameter integer DATA_WIDTH          = 8,
  parameter integer REGISTER_OUTPUT     = 0,
  parameter integer ENABLE_PARITY_CHECK = 0,
  parameter integer OP_MODE_WIDTH       = 2,
  parameter integer SWIZZLE_MAP_WIDTH   = $clog2(NUM_LANES)+1
)(
  input  wire                           clk,
  input  wire                           rst_n,
  input  wire                           bypass,
  input  wire [NUM_LANES*DATA_WIDTH-1:0]  data_in,
  input  wire [NUM_LANES*SWIZZLE_MAP_WIDTH-1:0] swizzle_map_flat,
  input  wire [OP_MODE_WIDTH-1:0]         operation_mode,
  output reg  [NUM_LANES*DATA_WIDTH-1:0]  data_out,
  output reg                            parity_error,
  output reg                            invalid_mapping_error
);

  // Unpack data_in into lanes
  wire [DATA_WIDTH-1:0] lane_in [0:NUM_LANES-1];
  genvar gi;
  generate
    for (gi = 0; gi < NUM_LANES; gi = gi + 1) begin : UNPACK_INPUT
      assign lane_in[gi] = data_in[DATA_WIDTH*(gi+1)-1 : DATA_WIDTH*gi];
    end
  endgenerate

  // Unpack swizzle_map_flat into swizzle_map array
  wire [SWIZZLE_MAP_WIDTH-1:0] swizzle_map [0:NUM_LANES-1];
  generate
    for (gi = 0; gi < NUM_LANES; gi = gi + 1) begin : UNPACK_SWIZZLE
      assign swizzle_map[gi] = swizzle_map_flat[SWIZZLE_MAP_WIDTH*(gi+1)-1 : SWIZZLE_MAP_WIDTH*gi];
    end
  endgenerate

  // Invalid mapping detection
  wire [NUM_LANES-1:0] invalid_map_flag;
  generate
    for (gi = 0; gi < NUM_LANES; gi = gi + 1) begin : INVALID_CHECK
      assign invalid_map_flag[gi] = (swizzle_map[gi] >= NUM_LANES) ? 1'b1 : 1'b0;
    end
  endgenerate
  wire invalid_mapping_detected = |invalid_map_flag;

  // Remap lanes according to swizzle_map or bypass
  wire [DATA_WIDTH-1:0] swizzled [0:NUM_LANES-1];
  generate
    for (gi = 0; gi < NUM_LANES; gi = gi + 1) begin : REMAP
      // Use lower bits of swizzle_map to index valid lanes.
      assign swizzled[gi] = bypass ? lane_in[gi] : lane_in[ swizzle_map[gi][$clog2(NUM_LANES)-1:0] ];
    end
  endgenerate

  // Pipeline Stage 1: Capture swizzled lanes
  reg [DATA_WIDTH-1:0] swizzle_reg [0:NUM_LANES-1];
  integer i;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      for (i = 0; i < NUM_LANES; i = i + 1)
        swizzle_reg[i] <= {DATA_WIDTH{1'b0}};
    else
      for (i = 0; i < NUM_LANES; i = i + 1)
        swizzle_reg[i] <= swizzled[i];
  end

  // Pipeline Stage 2: Capture operation mode and invalid mapping status
  reg [OP_MODE_WIDTH-1:0] op_reg;
  reg op_invalid_reg;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      op_reg <= {OP_MODE_WIDTH{1'b0}};
      op_invalid_reg <= 1'b0;
    end else begin
      op_reg <= operation_mode;
      op_invalid_reg <= invalid_mapping_detected;
    end
  end

  // Bit reversal function
  function automatic [DATA_WIDTH-1:0] bit_reverse;
    input [DATA_WIDTH-1:0] in;
    integer k;
    begin
      bit_reverse = {DATA_WIDTH{1'b0}};
      for (k = 0; k < DATA_WIDTH; k = k + 1)
        bit_reverse[k] = in[DATA_WIDTH-1-k];
    end
  endfunction

  // Pipeline Stage 3: Final output stage with bit reversal
  reg [DATA_WIDTH-1:0] final_reg [0:NUM_LANES-1];
  integer m;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      for (m = 0; m < NUM_LANES; m = m + 1)
        final_reg[m] <= {DATA_WIDTH{1'b0}};
    else
      for (m = 0; m < NUM_LANES; m = m + 1)
        final_reg[m] <= bit_reverse(swizzle_reg[m]);
  end

  // Pack final_reg into a flat output vector
  wire [NUM_LANES*DATA_WIDTH-1:0] final_packed;
  genvar q;
  generate
    for (q = 0; q < NUM_LANES; q = q + 1) begin : PACK_FINAL
      assign final_packed[DATA_WIDTH*(q+1)-1 : DATA_WIDTH*q] = final_reg[q];
    end
  endgenerate

  generate
    if (REGISTER_OUTPUT) begin : REG_FINAL
      always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
          data_out <= {NUM_LANES*DATA_WIDTH{1'b0}};
        else
          data_out <= final_packed;
      end
    end else begin : COMB_FINAL
      always @* begin
        data_out = final_packed;
      end
    end
  endgenerate

  // Updated parity error calculation using a generate block
  generate
    if (ENABLE_PARITY_CHECK) begin : GEN_PARITY
      // Calculate parity from final_reg if parity check is enabled.
      wire [NUM_LANES-1:0] final_parity;
      genvar p;
      for (p = 0; p < NUM_LANES; p = p + 1) begin : PARITY_CALC
        assign final_parity[p] = ^final_reg[p];
      end
      wire computed_parity = |final_parity;
      always @* begin
        parity_error = computed_parity;
      end
    end else begin : NO_PARITY
      // Drive parity_error to 0 when parity check is disabled.
      always @* begin
        parity_error = 1'b0;
      end
    end
  endgenerate

  // Pass the invalid mapping flag
  always @* begin
    invalid_mapping_error = op_invalid_reg;
  end

endmodule

context/verif/swizzler_tb.sv:
`timescale 1ns/1ps

module tb_swizzler;
  parameter NUM_LANES = 4;
  parameter DATA_WIDTH = 8;
  parameter REGISTER_OUTPUT = 1;
  parameter ENABLE_PARITY_CHECK = 0;
  parameter OP_MODE_WIDTH = 2;
  parameter SWIZZLE_MAP_WIDTH = 3;

  reg clk;
  reg rst_n;
  reg bypass;
  reg [NUM_LANES*DATA_WIDTH-1:0] data_in;
  reg [NUM_LANES*SWIZZLE_MAP_WIDTH-1:0] swizzle_map_flat;
  reg [OP_MODE_WIDTH-1:0] operation_mode;
  wire [NUM_LANES*DATA_WIDTH-1:0] data_out;
  wire parity_error;
  wire invalid_mapping_error;

  swizzler #(
    .NUM_LANES(NUM_LANES),
    .DATA_WIDTH(DATA_WIDTH),
    .REGISTER_OUTPUT(REGISTER_OUTPUT),
    .ENABLE_PARITY_CHECK(ENABLE_PARITY_CHECK),
    .OP_MODE_WIDTH(OP_MODE_WIDTH),
    .SWIZZLE_MAP_WIDTH(SWIZZLE_MAP_WIDTH)
  ) dut (
    .clk(clk),
    .rst_n(rst_n),
    .bypass(bypass),
    .data_in(data_in),
    .swizzle_map_flat(swizzle_map_flat),
    .operation_mode(operation_mode),
    .data_out(data_out),
    .parity_error(parity_error),
    .invalid_mapping_error(invalid_mapping_error)
  );

  reg [DATA_WIDTH-1:0] expected [0:NUM_LANES-1];
  reg [DATA_WIDTH-1:0] out_lane [0:NUM_LANES-1];
  integer i;

  function [DATA_WIDTH-1:0] bit_reverse;
    input [DATA_WIDTH-1:0] in;
    integer j;
    reg [DATA_WIDTH-1:0] out;
    begin
      out = 0;
      for(j = 0; j < DATA_WIDTH; j = j + 1)
        out[j] = in[DATA_WIDTH-1-j];
      bit_reverse = out;
    end
  endfunction

  function [DATA_WIDTH-1:0] get_lane;
    input integer index;
    begin
      get_lane = data_out[DATA_WIDTH*(index+1)-1 -: DATA_WIDTH];
    end
  endfunction

  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  initial begin
    rst_n = 0;
    bypass = 0;
    data_in = 0;
    swizzle_map_flat = 0;
    operation_mode = 0;
    #12;
    rst_n = 1;
    repeat (5) @(posedge clk);
    // TEST 1: Bypass disabled, identity mapping with bit reversal.
    data_in = {8'h04, 8'h03, 8'h02, 8'h01};
    swizzle_map_flat = {3'b011, 3'b010, 3'b001, 3'b000};
    bypass = 0;
    operation_mode = 0;
    repeat (5) @(posedge clk);
    for(i = 0; i < NUM_LANES; i = i + 1)
      out_lane[i] = get_lane(i);
    expected[0] = bit_reverse(8'h01);
    expected[1] = bit_reverse(8'h02);
    expected[2] = bit_reverse(8'h03);
    expected[3] = bit_reverse(8'h04);
    if(out_lane[0]==expected[0] && out_lane[1]==expected[1] &&
       out_lane[2]==expected[2] && out_lane[3]==expected[3])
      $display("TEST 1 PASS");
    else
      $display("TEST 1 FAIL: Expected %h %h %h %h, Got %h %h %h %h",
               expected[0], expected[1], expected[2], expected[3],
               out_lane[0], out_lane[1], out_lane[2], out_lane[3]);
    if(invalid_mapping_error==0)
      $display("TEST 1 INVALID MAPPING PASS");
    else
      $display("TEST 1 INVALID MAPPING FAIL");

    // TEST 2: Reverse mapping.
    data_in = {8'hAA, 8'hBB, 8'hCC, 8'hDD};
    swizzle_map_flat = {3'b000, 3'b001, 3'b010, 3'b011};
    bypass = 0;
    operation_mode = 0;
    repeat (5) @(posedge clk);
    for(i = 0; i < NUM_LANES; i = i + 1)
      out_lane[i] = get_lane(i);
    // Expected output is reversed compared to input lane order.
    expected[0] = bit_reverse(8'hAA);
    expected[1] = bit_reverse(8'hBB);
    expected[2] = bit_reverse(8'hCC);
    expected[3] = bit_reverse(8'hDD);
    if(out_lane[0]==expected[0] && out_lane[1]==expected[1] &&
       out_lane[2]==expected[2] && out_lane[3]==expected[3])
      $display("TEST 2 PASS");
    else
      $display("TEST 2 FAIL: Expected %h %h %h %h, Got %h %h %h %h",
               expected[0], expected[1], expected[2], expected[3],
               out_lane[0], out_lane[1], out_lane[2], out_lane[3]);

    // TEST 3: Bypass mode active.
    data_in = {8'h11, 8'h22, 8'h33, 8'h44};
    swizzle_map_flat = {3'b001, 3'b000, 3'b011, 3'b010};
    bypass = 1;
    operation_mode = 0;
    repeat (5) @(posedge clk);
    for(i = 0; i < NUM_LANES; i = i + 1)
      out_lane[i] = get_lane(i);
    expected[0] = bit_reverse(8'h44);
    expected[1] = bit_reverse(8'h33);
    expected[2] = bit_reverse(8'h22);
    expected[3] = bit_reverse(8'h11);
    if(out_lane[0]==expected[0] && out_lane[1]==expected[1] &&
       out_lane[2]==expected[2] && out_lane[3]==expected[3])
      $display("TEST 3 PASS");
    else
      $display("TEST 3 FAIL: Expected %h %h %h %h, Got %h %h %h %h",
               expected[0], expected[1], expected[2], expected[3],
               out_lane[0], out_lane[1], out_lane[2], out_lane[3]);

    // TEST 4: Invalid mapping detection.
    data_in = {8'h55, 8'h66, 8'h77, 8'h88};
    swizzle_map_flat = {3'b011, 3'b010, 3'b001, 3'b100};
    bypass = 0;
    operation_mode = 0;
    repeat (5) @(posedge clk);
    if(invalid_mapping_error==1)
      $display("TEST 4 PASS: Invalid mapping detected");
    else
      $display("TEST 4 FAIL: Invalid mapping not detected");
    $finish;
  end

endmodule

context/rtl/thermostat.v:
module thermostat (
    input wire [5:0] i_temp_feedback, // Temperature feedback bits
    input wire i_fan_on,             // Manual fan control
    input wire i_enable,             // Enable thermostat
    input wire i_fault,              // Fault signal
    input wire i_clr,                // Clear fault signal
    input wire i_clk,                // Clock input
    input wire i_rst,                // Asynchronous reset (active-low)

    output reg o_heater_full,
    output reg o_heater_medium,
    output reg o_heater_low,
    output reg o_aircon_full,
    output reg o_aircon_medium,
    output reg o_aircon_low,
    output reg o_fan,
    output reg [2:0] o_state         // FSM state output
);

// State encoding
localparam [2:0] HEAT_LOW  = 3'b000,
                 HEAT_MED  = 3'b001,
                 HEAT_FULL = 3'b010,
                 AMBIENT   = 3'b011,
                 COOL_LOW  = 3'b100,
                 COOL_MED  = 3'b101,
                 COOL_FULL = 3'b110;

// Internal signals
reg [2:0] current_state, next_state; // FSM state registers
reg heater_full, heater_medium, heater_low;
reg aircon_full, aircon_medium, aircon_low;
reg fan;

assign o_state = current_state;
// Sequential logic for state transitions and registered outputs
always @(posedge i_clk or negedge i_rst) begin
    if (!i_rst) begin
        // Asynchronous reset
        current_state <= AMBIENT;
        o_heater_full <= 0;
        o_heater_medium <= 0;
        o_heater_low <= 0;
        o_aircon_full <= 0;
        o_aircon_medium <= 0;
        o_aircon_low <= 0;
        o_fan <= 0;
    end else begin
        // Normal state transition
        current_state <= next_state;
        // Update registered outputs
        o_heater_full <= heater_full;
        o_heater_medium <= heater_medium;
        o_heater_low <= heater_low;
        o_aircon_full <= aircon_full;
        o_aircon_medium <= aircon_medium;
        o_aircon_low <= aircon_low;
        o_fan <= fan || i_fan_on;
    end
end

// Combinational logic for next state and intermediate outputs
always @(*) begin
    if (!i_enable || i_fault) begin
        // Handle fault or disable
        next_state = AMBIENT;
        heater_full = 0;
        heater_medium = 0;
        heater_low = 0;
        aircon_full = 0;
        aircon_medium = 0;
        aircon_low = 0;
        fan = 0;
    end else begin
        case (current_state)
            // Heating states
            HEAT_LOW: begin
                heater_full = 0;
                heater_medium = 0;
                heater_low = 1;
                aircon_full = 0;
                aircon_medium = 0;
                aircon_low = 0;
                fan = 1;
                if (i_temp_feedback[5]) begin 
                    next_state = HEAT_FULL; 
                end// Full cold
                else if (i_temp_feedback[0]) begin // Full hot
                    next_state = COOL_FULL;
                end
                else begin
                    if (i_temp_feedback[4]) begin 
                        next_state = HEAT_MED; 
                    end// Medium cold
                    else if (i_temp_feedback[1]) begin // Medium hot
                        next_state = COOL_MED;
                    end
                    else begin
                        if (i_temp_feedback[3]) begin 
                            next_state = HEAT_LOW; 
                        end// Low cold
                        else if (i_temp_feedback[2]) begin // Low hot
                            next_state = COOL_LOW;
                        end
                        else begin
                            next_state = AMBIENT;
                        end
                    end
                end
            end

            HEAT_MED: begin
                heater_full = 0;
                heater_medium = 1;
                heater_low = 0;
                aircon_full = 0;
                aircon_medium = 0;
                aircon_low = 0;
                fan = 1;
                if (i_temp_feedback[5]) begin 
                    next_state = HEAT_FULL; 
                end// Full cold
                else if (i_temp_feedback[0]) begin // Full hot
                    next_state = COOL_FULL;
                end
                else begin
                    if (i_temp_feedback[4]) begin 
                        next_state = HEAT_MED; 
                    end// Medium cold
                    else if (i_temp_feedback[1]) begin // Medium hot
                        next_state = COOL_MED;
                    end
                    else begin
                        if (i_temp_feedback[3]) begin 
                            next_state = HEAT_LOW; 
                        end// Low cold
                        else if (i_temp_feedback[2]) begin // Low hot
                            next_state = COOL_LOW;
                        end
                        else begin
                            next_state = AMBIENT;
                        end
                    end
                end
            end

            HEAT_FULL: begin
                heater_full = 1;
                heater_medium = 0;
                heater_low = 0;
                aircon_full = 0;
                aircon_medium = 0;
                aircon_low = 0;
                fan = 1;
                if (i_temp_feedback[5]) begin 
                    next_state = HEAT_FULL; 
                end// Full cold
                else if (i_temp_feedback[0]) begin // Full hot
                    next_state = COOL_FULL;
                end
                else begin
                    if (i_temp_feedback[4]) begin 
                        next_state = HEAT_MED; 
                    end// Medium cold
                    else if (i_temp_feedback[1]) begin // Medium hot
                        next_state = COOL_MED;
                    end
                    else begin
                        if (i_temp_feedback[3]) begin 
                            next_state = HEAT_LOW; 
                        end// Low cold
                        else if (i_temp_feedback[2]) begin // Low hot
                            next_state = COOL_LOW;
                        end
                        else begin
                            next_state = AMBIENT;
                        end
                    end
                end
            end

            // Cooling states
            COOL_LOW: begin
                heater_full = 0;
                heater_medium = 0;
                heater_low = 0;
                aircon_full = 0;
                aircon_medium = 0;
                aircon_low = 1;
                fan = 1;
                if (i_temp_feedback[5]) begin 
                    next_state = HEAT_FULL; 
                end// Full cold
                else if (i_temp_feedback[0]) begin // Full hot
                    next_state = COOL_FULL;
                end
                else begin
                    if (i_temp_feedback[4]) begin 
                        next_state = HEAT_MED; 
                    end// Medium cold
                    else if (i_temp_feedback[1]) begin // Medium hot
                        next_state = COOL_MED;
                    end
                    else begin
                        if (i_temp_feedback[3]) begin 
                            next_state = HEAT_LOW; 
                        end// Low cold
                        else if (i_temp_feedback[2]) begin // Low hot
                            next_state = COOL_LOW;
                        end
                        else begin
                            next_state = AMBIENT;
                        end
                    end
                end
            end

            COOL_MED: begin
                heater_full = 0;
                heater_medium = 0;
                heater_low = 0;
                aircon_full = 0;
                aircon_medium = 1;
                aircon_low = 0;
                fan = 1;
                aircon_medium = 1;
                if (i_temp_feedback[5]) begin 
                    next_state = HEAT_FULL; 
                end// Full cold
                else if (i_temp_feedback[0]) begin // Full hot
                    next_state = COOL_FULL;
                end
                else begin
                    if (i_temp_feedback[4]) begin 
                        next_state = HEAT_MED; 
                    end// Medium cold
                    else if (i_temp_feedback[1]) begin // Medium hot
                        next_state = COOL_MED;
                    end
                    else begin
                        if (i_temp_feedback[3]) begin 
                            next_state = HEAT_LOW; 
                        end// Low cold
                        else if (i_temp_feedback[2]) begin // Low hot
                            next_state = COOL_LOW;
                        end
                        else begin
                            next_state = AMBIENT;
                        end
                    end
                end
            end

            COOL_FULL: begin
                heater_full = 0;
                heater_medium = 0;
                heater_low = 0;
                aircon_full = 1;
                aircon_medium = 0;
                aircon_low = 0;
                fan = 1;
                if (i_temp_feedback[5]) begin 
                    next_state = HEAT_FULL; 
                end// Full cold
                else if (i_temp_feedback[0]) begin // Full hot
                    next_state = COOL_FULL;
                end
                else begin
                    if (i_temp_feedback[4]) begin 
                        next_state = HEAT_MED; 
                    end// Medium cold
                    else if (i_temp_feedback[1]) begin // Medium hot
                        next_state = COOL_MED;
                    end
                    else begin
                        if (i_temp_feedback[3]) begin 
                            next_state = HEAT_LOW; 
                        end// Low cold
                        else if (i_temp_feedback[2]) begin // Low hot
                            next_state = COOL_LOW;
                        end
                        else begin
                            next_state = AMBIENT;
                        end
                    end
                end
            end

            // Ambient state
            AMBIENT: begin
                heater_full = 0;
                heater_medium = 0;
                heater_low = 0;
                aircon_full = 0;
                aircon_medium = 0;
                aircon_low = 0;
                fan = 0;
                if (i_temp_feedback[5]) begin 
                    next_state = HEAT_FULL; 
                end// Full cold
                else if (i_temp_feedback[0]) begin // Full hot
                    next_state = COOL_FULL;
                end
                else begin
                    if (i_temp_feedback[4]) begin 
                        next_state = HEAT_MED; 
                    end// Medium cold
                    else if (i_temp_feedback[1]) begin // Medium hot
                        next_state = COOL_MED;
                    end
                    else begin
                        if (i_temp_feedback[3]) begin 
                            next_state = HEAT_LOW; 
                        end// Low cold
                        else if (i_temp_feedback[2]) begin // Low hot
                            next_state = COOL_LOW;
                        end
                        else begin
                            next_state = AMBIENT;
                        end
                    end
                end
            end

            default: next_state = AMBIENT; // Safety fallback
        endcase
    end
end

endmodule

context/verif/signed_comparator_tb.sv:
`timescale 1ns/1ps

module tb_signed_comparator;

reg clk;
reg rst_n;
reg enable;
reg bypass;
reg signed [15:0] a;
reg signed [15:0] b;
wire gt, lt, eq;

localparam DATA_WIDTH       = 16;
localparam REGISTER_OUTPUT  = 1;
localparam ENABLE_TOLERANCE = 1;
localparam TOLERANCE        = 2;
localparam SHIFT_LEFT       = 1;

signed_comparator #(
  .DATA_WIDTH(DATA_WIDTH),
  .REGISTER_OUTPUT(REGISTER_OUTPUT),
  .ENABLE_TOLERANCE(ENABLE_TOLERANCE),
  .TOLERANCE(TOLERANCE),
  .SHIFT_LEFT(SHIFT_LEFT)
) dut (
  .clk(clk),
  .rst_n(rst_n),
  .enable(enable),
  .bypass(bypass),
  .a(a),
  .b(b),
  .gt(gt),
  .lt(lt),
  .eq(eq)
);

always #5 clk = ~clk;

initial begin
  clk = 0;
  rst_n = 0;
  enable = 0;
  bypass = 0;
  a = 0;
  b = 0;
  repeat(2) @(posedge clk);
  rst_n = 1;
  repeat(2) @(posedge clk);

  test_case( 100,  100, 0, 1);
  test_case(  10,  -10, 0, 1);
  test_case(  -5,    5, 0, 1);
  test_case(  50,   52, 0, 1);  // near difference -> tolerance
  test_case(  51,   52, 0, 1);  // difference 1 -> eq due to TOLERANCE=2
  test_case(  53,   50, 0, 1);  // difference 3 -> not within tolerance
  test_case( 123, -123, 1, 1);  // bypass => eq=1
  test_case( 500, -500, 0, 0);  // enable=0 => eq=0,gt=0,lt=0
  repeat(2) @(posedge clk);

  integer i;
  for (i = 0; i < 5; i = i + 1) begin
    test_case($random, $random, $random%2, $random%2);
  end

  $finish;
end

task test_case;
  input signed [15:0] a_val;
  input signed [15:0] b_val;
  input bypass_val;
  input enable_val;
begin
  a = a_val;
  b = b_val;
  bypass = bypass_val;
  enable = enable_val;
  @(posedge clk);
  @(posedge clk);

  check_output(a_val, b_val, bypass_val, enable_val);
end
endtask

task check_output;
  input signed [15:0] a_val;
  input signed [15:0] b_val;
  input bypass_val;
  input enable_val;
  reg signed [DATA_WIDTH-1:0] a_shift, b_shift;
  reg signed [DATA_WIDTH:0] diff_abs;
  reg exp_gt, exp_lt, exp_eq;
begin
  a_shift = a_val <<< SHIFT_LEFT;
  b_shift = b_val <<< SHIFT_LEFT;
  diff_abs = (a_shift - b_shift);
  if (diff_abs < 0) diff_abs = -diff_abs;

  if (bypass_val) begin
    exp_gt = 0; exp_lt = 0; exp_eq = 1;
  end else if (!enable_val) begin
    exp_gt = 0; exp_lt = 0; exp_eq = 0;
  end else begin
    if (ENABLE_TOLERANCE && (diff_abs <= TOLERANCE)) begin
      exp_gt = 0; exp_lt = 0; exp_eq = 1;
    end else if (a_shift > b_shift) begin
      exp_gt = 1; exp_lt = 0; exp_eq = 0;
    end else if (a_shift < b_shift) begin
      exp_gt = 0; exp_lt = 1; exp_eq = 0;
    end else begin
      exp_gt = 0; exp_lt = 0; exp_eq = 1;
    end
  end

  if (gt !== exp_gt || lt !== exp_lt || eq !== exp_eq) begin
    $display("Time=%0t FAIL: a=%d b=%d bypass=%b en=%b SHIFT_LEFT=%0d TOL=%0d => gt=%b lt=%b eq=%b (exp: %b %b %b)",
      $time, a_val, b_val, bypass_val, enable_val, SHIFT_LEFT, TOLERANCE,
      gt, lt, eq, exp_gt, exp_lt, exp_eq);
  end else begin
    $display("Time=%0t PASS: a=%d b=%d bypass=%b en=%b SHIFT_LEFT=%0d TOL=%0d => gt=%b lt=%b eq=%b",
      $time, a_val, b_val, bypass_val, enable_val, SHIFT_LEFT, TOLERANCE, gt, lt, eq);
  end
end
endtask

endmodule

context/rtl/sorting_engine.sv:
module sorting_engine #(parameter WIDTH = 8)(
    input                     clk,
    input                     rst,
    input                     start,      // Start the sort when start=1
    input  [8*WIDTH-1:0]      in_data,    // 8 inputs, each WIDTH bits
    output reg                done,
    output reg [8*WIDTH-1:0]  out_data    // 8 outputs, sorted ascending
);

  // FSM state encoding
  localparam IDLE      = 3'd0,
             LOAD      = 3'd1,
             SORT_PAIRS= 3'd2,
             MERGE_2_1 = 3'd3,  // Merge first two sorted pairs into a 4-element group
             MERGE_2_2 = 3'd4,  // Merge second two sorted pairs into a 4-element group
             MERGE_4   = 3'd5,  // Merge the two 4-element groups into final 8-element sorted list
             DONE      = 3'd6;

  reg [2:0] state;

  // Internal storage for data at different stages.
  reg [WIDTH-1:0] stage0 [7:0];           // Loaded input data
  reg [WIDTH-1:0] sorted_pairs [7:0];     // After pair compare–swap
  reg [WIDTH-1:0] merge4_right [3:0];      // First 4–element sorted group (from indices 0–3)
  reg [WIDTH-1:0] merge4_left [3:0];     // Second 4–element sorted group (from indices 4–7)
  reg [WIDTH-1:0] final_sorted [7:0];     // Final 8–element sorted result

  // Merge pointers and counter used for sequential merging
  reg [3:0] merge_count;  // Counts how many outputs have been merged in current merge stage
  reg [2:0] ptr1, ptr2;   // Pointers for the two arrays being merged

  integer i; // loop variable for for–loops

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      state      <= IDLE;
      done       <= 0;
      out_data   <= 0;
      merge_count<= 0;
      ptr1       <= 0;
      ptr2       <= 0;
    end else begin
      case (state)
        // Wait for the start signal.
        IDLE: begin
          done <= 0;
          if (start)
            state <= LOAD;
        end

        // Capture the 8 input elements from the flat bus into an array.
        LOAD: begin
          for (i = 0; i < 8; i = i + 1) begin
            stage0[i] <= in_data[i*WIDTH +: WIDTH];
          end
          state <= SORT_PAIRS;
        end

        // Stage 1: Compare-swap each adjacent pair.
        // The 8 numbers are divided into 4 pairs: indices {0,1}, {2,3}, {4,5}, {6,7}.
        SORT_PAIRS: begin
          // Pair 0
          if (stage0[0] <= stage0[1]) begin
            sorted_pairs[0] <= stage0[0];
            sorted_pairs[1] <= stage0[1];
          end else begin
            sorted_pairs[0] <= stage0[1];
            sorted_pairs[1] <= stage0[0];
          end
          // Pair 1
          if (stage0[2] <= stage0[3]) begin
            sorted_pairs[2] <= stage0[2];
            sorted_pairs[3] <= stage0[3];
          end else begin
            sorted_pairs[2] <= stage0[3];
            sorted_pairs[3] <= stage0[2];
          end
          // Pair 2
          if (stage0[4] <= stage0[5]) begin
            sorted_pairs[4] <= stage0[4];
            sorted_pairs[5] <= stage0[5];
          end else begin
            sorted_pairs[4] <= stage0[5];
            sorted_pairs[5] <= stage0[4];
          end
          // Pair 3
          if (stage0[6] <= stage0[7]) begin
            sorted_pairs[6] <= stage0[6];
            sorted_pairs[7] <= stage0[7];
          end else begin
            sorted_pairs[6] <= stage0[7];
            sorted_pairs[7] <= stage0[6];
          end
          // Initialize pointers for first merge stage (MERGE_2_1)
          ptr1        <= 0;
          ptr2        <= 0;
          merge_count <= 0;
          state       <= MERGE_2_1;
        end

        // Stage 2a: Merge the first two sorted pairs (indices 0–1 and 2–3)
        MERGE_2_1: begin
          // Use ptr1 for sorted_pairs[0:1] and ptr2 for sorted_pairs[2:3].
          if ((ptr1 < 2) && (ptr2 < 2)) begin
            if (sorted_pairs[ptr1] <= sorted_pairs[ptr2+2]) begin
              merge4_right[merge_count] <= sorted_pairs[ptr1];
              ptr1 <= ptr1 + 1;
            end else begin
              merge4_right[merge_count] <= sorted_pairs[ptr2+2];
              ptr2 <= ptr2 + 1;
            end
          end else if (ptr1 < 2) begin
            merge4_right[merge_count] <= sorted_pairs[ptr1];
            ptr1 <= ptr1 + 1;
          end else if (ptr2 < 2) begin
            merge4_right[merge_count] <= sorted_pairs[ptr2+2];
            ptr2 <= ptr2 + 1;
          end
          // Check if 4 elements have been merged.
          if (merge_count == 3) begin
            merge_count <= 0;
            ptr1        <= 0;
            ptr2        <= 0;
            state       <= MERGE_2_2;
          end else begin
            merge_count <= merge_count + 1;
          end
        end

        // Stage 2b: Merge the second two sorted pairs (indices 4–5 and 6–7)
        MERGE_2_2: begin
          // Use ptr1 for sorted_pairs[4:5] and ptr2 for sorted_pairs[6:7].
          if ((ptr1 < 2) && (ptr2 < 2)) begin
            if (sorted_pairs[ptr1+4] <= sorted_pairs[ptr2+6]) begin
              merge4_left[merge_count] <= sorted_pairs[ptr1+4];
              ptr1 <= ptr1 + 1;
            end else begin
              merge4_left[merge_count] <= sorted_pairs[ptr2+6];
              ptr2 <= ptr2 + 1;
            end
          end else if (ptr1 < 2) begin
            merge4_left[merge_count] <= sorted_pairs[ptr1+4];
            ptr1 <= ptr1 + 1;
          end else if (ptr2 < 2) begin
            merge4_left[merge_count] <= sorted_pairs[ptr2+6];
            ptr2 <= ptr2 + 1;
          end
          // Check if merge of 4 elements is complete.
          if (merge_count == 3) begin
            merge_count <= 0;
            ptr1        <= 0;
            ptr2        <= 0;
            state       <= MERGE_4;
          end else begin
            merge_count <= merge_count + 1;
          end
        end

        // Stage 3: Merge the two 4–element groups (merge4_right and merge4_left)
        MERGE_4: begin
          if ((ptr1 < 4) && (ptr2 < 4)) begin
            if (merge4_right[ptr1] <= merge4_left[ptr2]) begin
              final_sorted[merge_count] <= merge4_right[ptr1];
              ptr1 <= ptr1 + 1;
            end else begin
              final_sorted[merge_count] <= merge4_left[ptr2];
              ptr2 <= ptr2 + 1;
            end
          end else if (ptr1 < 4) begin
            final_sorted[merge_count] <= merge4_right[ptr1];
            ptr1 <= ptr1 + 1;
          end else if (ptr2 < 4) begin
            final_sorted[merge_count] <= merge4_left[ptr2];
            ptr2 <= ptr2 + 1;
          end
          // Check if all 8 elements have been merged.
          if (merge_count == 7) begin
            merge_count <= 0;
            state       <= DONE;
          end else begin
            merge_count <= merge_count + 1;
          end
        end

        // Final state: pack the final_sorted array back into out_data and assert done.
        DONE: begin
          for (i = 0; i < 8; i = i + 1) begin
            out_data[i*WIDTH +: WIDTH] <= final_sorted[i];
          end
          done  <= 1;
          // Optionally, return to IDLE (or hold in DONE) so a new sort can begin.
          state <= IDLE;
        end

        default: state <= IDLE;
      endcase
    end
  end
    
endmodule
